/// STEP SEQ's hint line: while held, how to pick a sound; on, what a
/// press does.
fn step_seq_hint(s: crate::app::StepPads) -> String {
    if s.picking && s.line() {
        return "STEP SEQ held:   play a pad, or hold a chord: new steps play it   ·   \
                let go alone: steps on or off"
            .to_string();
    }
    if s.picking {
        return "STEP SEQ held:   tap a pad: its steps go on the pads   ·   PAD BANK: the kit's bank   ·   \
                let go alone: steps on or off"
            .to_string();
    }
    let follow = if s.follow { "Follow off" } else { "Follow" };
    if s.line() {
        return format!(
            "STEP SEQ · page {}   ·   tap: the note on a step, or off   ·   PAD BANK: page   ·   \
             hold STEP SEQ + pads: the note or chord   ·   SHIFT + STEP SEQ: {follow}   ·   \
             ERASE + step or PAD BANK: clear   ·   STEP SEQ: the pads play again",
            s.page + 1
        );
    }
    format!(
        "STEP SEQ · page {}   ·   tap: a step on or off   ·   PAD BANK: page   ·   hold STEP SEQ + pad: sound   ·   \
         SHIFT + STEP SEQ: {follow}   ·   ERASE + step or PAD BANK: clear   ·   STEP SEQ: the pads play again",
        s.page + 1
    )
}
/// While COPY is held with the pads as steps.
fn step_copy_hint(s: crate::app::StepPads) -> String {
    match s.copy_page {
        Some(p) => format!(
            "COPY · page {} picked   ·   PAD BANK: the page it goes to   ·   UNDO takes it back",
            p + 1
        ),
        None => "COPY +   a step pad: pick it, then tap the steps it goes to   ·   \
                 PAD BANK: pick a page, then the PAD BANK it goes to   ·   UNDO takes it back"
            .to_string(),
    }
}

/// Where the steps are held from, for their hint: Play or Arrange (the
/// Q-Links set them), the Synth tab (a knob is a lock), or elsewhere.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HeldPlace {
    QLinks,
    Synth,
    Elsewhere,
}

/// While step pads are held: what the Q-Links of bank `bank` (or the
/// Synth tab's knobs) and another tap do. `line`: steps of the synth's
/// line, whose Step bank starts with the note and which take a keyboard's
/// keys.
fn step_held_hint(name: &str, bank: play_page::HeldBank, place: HeldPlace, line: bool) -> String {
    use play_page::HeldBank;
    let bank = match (place, bank) {
        (HeldPlace::Synth, _) => "a knob here: a lock   ·   ERASE: the locks off",
        (HeldPlace::Elsewhere, _) => "MAIN: Play, where the Q-Links set it",
        (HeldPlace::QLinks, HeldBank::Step) if line => {
            "Q-Links: note, velocity, length, chance   ·   keys: the notes   ·   Q-LINK: condition, ratchet"
        }
        (HeldPlace::QLinks, HeldBank::Step) => {
            "Q-Links: velocity, length, nudge, chance   ·   Q-LINK: condition, ratchet"
        }
        (HeldPlace::QLinks, HeldBank::Trig) => {
            "Q-Links: condition, ratchet, nudge, ramp   ·   Q-LINK: the sound's locks"
        }
        (HeldPlace::QLinks, HeldBank::Sound) => {
            "Q-Links: lock the sound   ·   ERASE: the locks off   ·   Q-LINK: velocity, length"
        }
    };
    format!(
        "{name} held   ·   {bank}   ·   tap a later step: the note lasts to it   ·   \
         after a turn, another step: set them together"
    )
}

