/// What each track plays as its own instrument (None: the kit), then
/// what each free place holds (step 6: a synth no track has).
pub type TrackSounds = [Option<crate::instruments::Held>; crate::instruments::HOLDERS];

/// The track whose instrument each track plays though it has none of its
/// own (instrument redesign step 4; None: it plays its kit).
pub type TrackSends = [Option<u8>; crate::instruments::TRACKS];

/// The instrument track `t` plays, from `sounds` and `sends`: its own
/// (with None), or another track's (with that track).
fn played(
    sounds: &TrackSounds,
    sends: &TrackSends,
    t: usize,
) -> Option<(crate::instruments::Held, Option<usize>)> {
    if let Some(h) = sounds.get(t).copied().flatten() {
        return Some((h, None));
    }
    let o = usize::from(sends.get(t).copied().flatten()?);
    sounds.get(o).copied().flatten().map(|h| (h, Some(o)))
}

/// An instrument's name as track `t` shows it: its own's ("FM"), or
/// another track's ("Track 3's FM").
fn played_name(h: crate::instruments::Held, from: Option<usize>) -> String {
    match from {
        Some(o) => crate::app::sent_name(o, h.name),
        None => h.name.to_string(),
    }
}

/// Why a track's pads have no mutes, in a line starting `what`: it plays
/// notes (the synth, or an instrument: `kit` None), and pad mutes are a
/// kit's. None on a kit: any kit's pads, on any bank, mute on their track
/// (the instrument redesign's step 10).
pub fn no_pad_mutes(what: &str, kit: Option<usize>) -> Option<String> {
    match kit {
        Some(_) => None,
        None => Some(format!(
            "{what}: this track plays notes, and pad mutes are a kit's: mute the track"
        )),
    }
}

/// Writes what each track plays under its name: its own instrument's
/// name, or another track's ("Track 3's FM", `sends`), else what it plays
/// of the list of kits (`kits`): "Kit" (kit 1), "Kit 2" and on, or
/// "Synth"; a Loop track's input ("Pads", for the pads and the synth).
/// And which tracks play notes, so transpose moves them
/// (`TrackInfo::melodic`): one with an instrument (not the drum engine),
/// or one that plays the synth while it plays notes (`synth_notes`).
fn fill_sounds(
    st: &mut TimeState,
    sounds: &TrackSounds,
    sends: &TrackSends,
    kits: &crate::sampler::TrackKits,
    synth_notes: bool,
) {
    use std::borrow::Cow;
    for (i, t) in st.tracks.iter_mut().enumerate() {
        let played = played(sounds, sends, i);
        let own = played.map(|(h, _)| h);
        let name: Cow<str> = match (t.loops, played) {
            (Some(input), _) => input.short().into(),
            (None, Some((h, from))) => played_name(h, from).into(),
            (None, None) if kits.plays_synth(i) => "Synth".into(),
            (None, None) => match kits.entry(i) {
                0 => "Kit".into(),
                k => format!("Kit {}", k + 1).into(),
            },
        };
        if t.sound != name {
            t.sound = name.into_owned();
        }
        t.melodic = t.loops.is_none()
            && match own {
                Some(h) => h.id != DRUMS_ENGINE,
                None => synth_notes && kits.plays_synth(i),
            };
    }
}

/// The drum synth's id: its notes are drums, so it never transposes.
const DRUMS_ENGINE: &str = "mpfree.drums";

/// The loops as the Loop tracks' cells show them, from the Looper's view:
/// each loop's layers and whether it overdubs, how many hold a loop, and
/// the memory in use.
fn loops_info(v: &crate::looping::LooperView) -> mpfree_time_ui::view::LoopsInfo {
    use mpfree_looper::Phase;
    let mut info = mpfree_time_ui::view::LoopsInfo::default();
    for (n, ((f, s), w)) in info
        .loops
        .iter_mut()
        .zip(&v.loops)
        .zip(&v.cell_waves)
        .enumerate()
    {
        f.overdubbing = s.phase == Phase::Overdubbing;
        f.copying = v.copy_into == Some(n) || s.copying.is_some();
        f.wave = *w;
    }
    info.in_use = v.loops.iter().filter(|s| s.phase != Phase::Empty).count();
    info.waiting = v.loops.iter().any(|s| s.phase == Phase::Armed);
    info.recording = v.loops.iter().any(|s| s.phase == Phase::Recording);
    let m = v.memory;
    info.memory_pct = (m.used * 100)
        .checked_div(m.capacity)
        .map_or(0, |p| p.min(100) as u8);
    info
}

