/// Tracks for the Pads tab's Kit of row (the sampler review's mockup 5):
/// track 1 armed on kit 1 with a clip, track 2 on the second kit by a
/// pick, and track 3 on the synth with a clip.
pub fn sample_kit_tracks(p: &mut Player) {
    use crate::time::{StepAction, TimeHost};
    let Ok(mut h) = TimeHost::new(44_100, 92.0) else {
        return;
    };
    for t in [2, 0] {
        let _ = h.act(TimeAction::Arm(Some(t)));
        let _ = h.step_action(StepAction::Tap {
            pad: 0,
            step: 0,
            velocity: 100,
        });
    }
    p.apply(ToUi::Time(Box::new(h.state())));
    let synth = p
        .kits
        .iter()
        .position(|k| k.synth.is_some())
        .unwrap_or(p.kits.len());
    let mut kits = crate::sampler::TrackKits::new(synth);
    kits.set(1, 1);
    kits.set(2, synth);
    p.apply(ToUi::TrackKits(Box::new(kits)));
}

/// A beat programmed on the Play page's pattern with the real sequencer
/// (mockup F's: kick, snare, hats, a clap, perc, bass and a chop), playing
/// at 92 BPM until `sixteenths` into bar 9, and the transport.
pub fn sample_pattern(p: &mut Player, sixteenths: i64) {
    use crate::time::{Pads, StepAction, TimeHost, STEP_TICKS};
    struct Quiet;
    impl Pads for Quiet {
        fn hit_at(&mut self, _: u16, _: usize, _: u8, _: u32) -> bool {
            true
        }
        fn release_at(&mut self, _: u16, _: usize, _: u32) {}
        fn stop_all(&mut self) {}
        fn pressure_at(&mut self, _: u16, _: usize, _: u8, _: u32) {}
    }
    let Ok(mut h) = TimeHost::new(44_100, 92.0) else {
        return;
    };
    let rows: [(u8, &str); 8] = [
        (0, "X... ..x. X.x. ...."),
        (2, ".... X... .... X..o"),
        (4, "x.xo x.xo x.xo x.Xo"),
        (5, ".... ...x .... ...."),
        (7, ".... X... .... X..."),
        (10, "..o. .o.. ..o. o..o"),
        (12, "X..x ..X. X... ..x."),
        (13, "X... .... ..x. ...."),
    ];
    for (pad, steps) in rows {
        for (i, c) in steps.chars().filter(|c| !c.is_whitespace()).enumerate() {
            let velocity = match c {
                'X' => 120,
                'x' => 84,
                'o' => 52,
                _ => continue,
            };
            let _ = h.step_action(StepAction::Tap {
                pad,
                step: i,
                velocity,
            });
        }
    }
    // The mockups' step 7 of the kick (velocity 96, 1/32 long, 4 ms
    // early) and their swing (56 %).
    for change in [
        mpfree_seq::steps::Change::Velocity(96),
        mpfree_seq::steps::Change::Length(STEP_TICKS / 2),
        mpfree_seq::steps::Change::Nudge(-6),
    ] {
        let _ = h.step_action(StepAction::Change {
            pad: 0,
            step: 6,
            change,
        });
    }
    // Mockup A's marks on the cells: conditions, a chance, ratchets, a
    // note held over the next step, and locks (one with no note).
    use mpfree_seq::steps::Change;
    use mpfree_seq::Cond;
    for (pad, step, change) in [
        (0, 8, Change::Cond(Cond::Every { a: 1, b: 2 })),
        (0, 10, Change::Chance(50)),
        (2, 15, Change::Ratchet(3)),
        (4, 12, Change::Cond(Cond::Pre)),
        (5, 7, Change::Length(STEP_TICKS * 2)),
        (7, 12, Change::Cond(Cond::Fill)),
        (10, 2, Change::Ratchet(2)),
        (12, 8, Change::Cond(Cond::First)),
        (13, 10, Change::Chance(70)),
    ] {
        let _ = h.step_action(StepAction::Change { pad, step, change });
    }
    let tune = |pad| {
        mpfree_play::mpfree_param::RelAddr::new(mpfree_play::mpfree_param::OnTrack::Pad(pad), 2)
    };
    for (pad, steps) in [(0u8, (1u128 << 6) | (1 << 9)), (2, 1 << 12), (10, 1 << 5)] {
        let _ = h.step_action(StepAction::Lock {
            pad,
            steps,
            addr: tune(pad),
            value: Some(300.0),
        });
    }
    h.command(mpfree_transport::Command::SetSwing(
        mpfree_transport::time::Swing {
            grid: 240,
            amount: 56,
        },
    ));
    h.command(mpfree_transport::Command::Play);
    let target = 8 * 3840 + sixteenths * STEP_TICKS;
    let mut q = Quiet;
    while h.info().position < target {
        h.advance(128);
        h.period(128, &mut q);
    }
    p.apply(ToUi::Time(Box::new(h.state())));
    p.apply(ToUi::Steps(Box::new(h.steps())));
}

/// Beats on a synth track, as the sequencer design's mockup B: the synth
/// on the pads in C minor, In key (C3 up), the timing strip off so the
/// pattern has eight rows, and a bass line with a C minor triad on step 1,
/// an accent, a 50 % note and a 1:2 note.
pub fn sample_beats_synth(fonts: Fonts) -> Player {
    use crate::time::{Pads, StepAction, TimeHost, STEP_TICKS};
    use mpfree_seq::steps::Change;
    let mut p = sample_player(fonts);
    let mut s = crate::synth::Synth::new(44_100);
    let mut set = s.settings();
    set.scale = mpfree_arp::scale::by_name("Minor")
        .map(|d| mpfree_arp::scale::Scale::with_down(0, d.mask, d.down));
    set.set_layout(mpfree_arp::scale::pads::PadLayout::InKey);
    s.set_settings(set);
    let synth_kit = sample_kits().len();
    p.apply(ToUi::KitChanged {
        kit: synth_kit,
        view: s.kit_view(),
    });
    p.apply(ToUi::Kit(synth_kit));
    let mut settings = p.settings.clone();
    settings.timing_strip = false;
    p.apply(ToUi::Settings(settings));
    struct Quiet;
    impl Pads for Quiet {
        fn hit_at(&mut self, _: u16, _: usize, _: u8, _: u32) -> bool {
            true
        }
        fn release_at(&mut self, _: u16, _: usize, _: u32) {}
        fn stop_all(&mut self) {}
        fn pressure_at(&mut self, _: u16, _: usize, _: u8, _: u32) {}
    }
    let Ok(mut h) = TimeHost::new(44_100, 92.0) else {
        return p;
    };
    // (pad, step, velocity, steps long): C3 is pad 1, Eb3 pad 3, G3 pad 5.
    let notes: [(u8, usize, u8, i64); 11] = [
        (0, 0, 100, 3),
        (2, 0, 100, 3),
        (4, 0, 100, 3),
        (4, 4, 90, 1),
        (6, 6, 96, 2),
        (7, 8, 127, 1),
        (5, 10, 84, 2),
        (3, 12, 90, 1),
        (4, 13, 90, 1),
        (2, 14, 96, 2),
        (0, 14, 70, 1),
    ];
    for (pad, step, velocity, len) in notes {
        let _ = h.step_action(StepAction::Tap {
            pad,
            step,
            velocity,
        });
        if len > 1 {
            let _ = h.step_action(StepAction::Change {
                pad,
                step,
                change: Change::Length(STEP_TICKS * len),
            });
        }
    }
    for (pad, step, change) in [
        (5, 10, Change::Chance(50)),
        (2, 14, Change::Cond(mpfree_seq::Cond::Every { a: 1, b: 2 })),
    ] {
        let _ = h.step_action(StepAction::Change { pad, step, change });
    }
    let mut q = Quiet;
    h.period(128, &mut q);
    p.apply(ToUi::Time(Box::new(h.state())));
    p.apply(ToUi::Steps(Box::new(h.steps())));
    p.apply(ToUi::Show(View::Sequencer));
    p.outbox.retain(|a| !matches!(a, FromUi::Arm(_)));
    let _ = p.take_actions();
    p.ui.invalidate();
    p
}

/// Hits played on the pads over the last two bars, a little off the grid
/// as hands are (mostly early, as mockup I), for Beats' timing strip.
pub fn sample_hits(p: &mut Player) {
    let t = p.play.transport;
    let bar = t.meter.bar_ticks() as f64;
    let now = t.position as f64;
    let hash = |i: u32| {
        let x = i.wrapping_mul(2_654_435_761).rotate_left(13) ^ 0x9E37_79B9;
        (x % 1000) as f64 / 1000.0
    };
    let lanes: [(u8, &str); 4] = [
        (0, "X... ..x. X.x. ...."),
        (2, ".... X... .... X..."),
        (4, "x.x. x.x. x.x. x.x."),
        (13, ".... ..x. ..x. ...."),
    ];
    let mut k = 0u32;
    let start = (now / (2.0 * bar)).floor() * 2.0 * bar - 2.0 * bar;
    for b in 0..4 {
        for (pad, steps) in lanes {
            for (i, c) in steps.chars().filter(|c| !c.is_whitespace()).enumerate() {
                if c == '.' {
                    continue;
                }
                k += 1;
                let grid = start + b as f64 * bar + i as f64 * 240.0;
                // About 6 ms early on average, spread ±9 ms, at 92 BPM.
                let ms = -6.0 + (hash(k) - 0.5) * 18.0;
                let tick = grid + ms * 92.0 * 960.0 / 60_000.0;
                if tick > now || tick < now - 2.0 * bar {
                    continue;
                }
                let velocity = if c == 'X' { 112 } else { 70 } + (hash(k + 99) * 14.0) as u8;
                p.apply(ToUi::Hit(HitInfo {
                    pad,
                    velocity,
                    tick,
                    bpm: 92.0,
                    bar_ticks: bar as i64,
                }));
            }
        }
    }
}

/// The Play page as mockups F to I show it, with the app's real state
/// behind it: kit 2, the recorded loop, the programmed beat playing, the
/// master near full with the limiter just catching, a throw held, and the
/// view's own touches (a step picked in Beats, the hits in Drum).
pub fn sample_play(fonts: Fonts, v: PlayView) -> Player {
    let mut p = sample_player(fonts);
    p.apply(ToUi::Kit(1));
    for pad in 0..16 {
        p.apply(ToUi::PadUp(pad));
    }
    if let Some(g) =
        p.ui.get_mut::<MiniPads>(play_page::PADS)
            .map(|m| &mut m.grid)
    {
        for pad in g.pads.iter_mut() {
            pad.held = false;
            pad.level = 0.0;
        }
        g.pads[4].level = 0.9;
        g.pads[13].level = 0.55;
    }
    p.apply(ToUi::Status(Status {
        shift: false,
        pad_level: PadLevel::Off,
        repeat: false,
        latched: false,
        rate: "1/16",
        bpm: 92.0,
        mute_keys: MuteKeys::Off,
        mute_bank: 0,
        loop_keys: false,
        perform: None,
        perform_bank: 0,
        steps: None,
        erase: false,
        copy: false,
        half_level: 64,
        main_held: None,
        full_held: false,
        tap_held: false,
    }));
    match v {
        PlayView::All => sample_busy_loops(&mut p),
        PlayView::Beats => sample_loop(&mut p),
    }
    let at = match v {
        PlayView::All => 1,
        PlayView::Beats => 6,
    };
    sample_pattern(&mut p, at);
    // The kits' projects (Boom Bap's pads with sounds behind them), so the
    // Tune and Decay Q-Links read the pads' own settings.
    p.apply(ToUi::SampleKits {
        projects: vec![mpfree_sampler::model::Project::new(), boom_bap_project()],
        rate: 44_100,
    });
    p.play.last_pad = 0;
    p.apply(ToUi::Level { db: -1.5 });
    for _ in 0..3 {
        p.apply(ToUi::Meter {
            peak_db: [-4.5, -6.0],
            limit_db: 1.2,
        });
    }
    // Pad 8 muted on the track the steps show (step 10: the track's).
    let shown = p.play.steps.track;
    if let Some(t) = p.time.tracks.get_mut(shown) {
        t.pad_mutes = 1 << 7;
    }
    p.play.pad_mutes = 1 << 7;
    let mut levels = p.play.levels;
    levels.drums_filter = -16.0;
    levels.loop_db = -3.0;
    levels.line_db = 6.0;
    levels.loop_filter = -22.0;
    levels.drums_send_db = 20.0 * 0.22f32.log10();
    p.apply(ToUi::PlayLevels(levels));
    let shared = Arc::new(crate::engines::EngineShared::default());
    let mut probes = crate::engines::EngineProbes::with_shared(Arc::clone(&shared));
    for _ in 0..200 {
        probes.add(crate::engines::PERIOD, Duration::from_micros(610));
    }
    probes.publish();
    p.apply(ToUi::Engines(shared));
    if v == PlayView::Beats {
        // Beats' pages are the Sequencer's Steps.
        p.apply(ToUi::Show(View::Sequencer));
    } else {
        p.show_play_view(v);
    }
    // (The view arming what it shows, for a desk there is none of here.)
    p.outbox.retain(|a| !matches!(a, FromUi::Arm(_)));
    match v {
        PlayView::All => {
            p.play.throw(2, true);
            p.play.xy.touch(0.68, 0.62);
            // A tap switched the hat's step 9 off and kept it (step 3b):
            // the outline with "off" in it.
            if let Some(c) = p.play.steps.clip.as_mut() {
                for (pitch, row) in c.rows.iter_mut() {
                    if *pitch == 4 {
                        if let Some(Some(st)) = row.get_mut(8) {
                            st.on = false;
                        }
                    }
                }
            }
        }
        PlayView::Beats => {
            // Your timing's strip, from two bars of hits.
            sample_hits(&mut p);
            p.play.selected = Some((0, 6));
            p.play.throw(2, true);
            p.apply(ToUi::QLinkTouch(0, true));
        }
    }
    if let Some(xy) = p.ui.get_mut::<XyPad>(play_page::XY) {
        (xy.x, xy.y) = p.play.xy.position();
        xy.on = p.play.xy.touched();
        if xy.on {
            // The finger's way up to where it is, as the mockups draw it.
            let (x, y) = p.play.xy.position();
            let trail: Vec<(f32, f32)> = (0..10)
                .map(|k| {
                    let f = k as f32 / 10.0;
                    (0.3 + (x - 0.3) * f, 0.12 + (y - 0.12) * f * f)
                })
                .collect();
            xy.set_trail(&trail);
        }
    }
    p.refresh_play();
    p.refresh_chips();
    p.refresh_qlinks();
    p
}

/// Boom Bap's sampler project for the previews: a short made-up sound on
/// each of its 16 pads, with the mockups' settings on Kick (-2 st) and Hat
/// (+2 st, 180 ms decay).
fn boom_bap_project() -> mpfree_sampler::model::Project {
    use mpfree_sampler::model::{Layer, Pad, Project, Region, Source};
    let mut p = Project::new();
    let names = [
        "Kick", "Kick 2", "Snare", "Rim", "Hat", "Hat op", "Shaker", "Clap", "Conga", "Tom",
        "Perc", "Crash", "Bass", "Chop 1", "Chop 2", "Vox",
    ];
    for (i, name) in names.iter().enumerate() {
        let data: Vec<f32> = (0..2_000)
            .map(|n| (n as f32 * 0.05 * (i + 1) as f32).sin() * (1.0 - n as f32 / 2_000.0))
            .collect();
        let source = Source::new(name, 44_100, 1, data).expect("a sound");
        let region = Region::whole(&source);
        p.add_source(source);
        let mut pad = Pad::new(name, Layer::new(region));
        match i {
            0 => pad.tune_cents = -200,
            4 => {
                pad.tune_cents = 200;
                pad.amp.sustain = 0.0;
                pad.amp.decay_ms = 180.0;
            }
            _ => {}
        }
        p.set_pad(i, Some(pad), None).expect("a pad");
    }
    p
}

/// Hands the app's effects to the screen as the audio thread does (lights,
/// sounds and kit changes are left out), for previews and tests.
/// The Touch page's two screens, built in their own frame: `sample_screens`
/// already holds many players on its stack.
#[inline(never)]
fn push_touch_dev_samples(out: &mut Vec<(&'static str, Player)>, fonts: &impl Fn() -> Fonts) {
    out.push(("debug-touch", touch_dev_sample(fonts(), false)));
    out.push(("debug-touch-targets", touch_dev_sample(fonts(), true)));
}

/// The Touch page with made-up measurements, on a clock of its own (so the
/// picture is the same every time).
#[inline(never)]
pub fn touch_dev_sample(fonts: Fonts, targets: bool) -> Player {
    use std::sync::atomic::{AtomicU64, Ordering};
    let mut p = sample_player(fonts);
    p.apply(ToUi::Settings(Settings {
        debug_mode: true,
        ..Settings::default()
    }));
    let mut saved = Tuning::default();
    saved.set(Param::OffsetY, 2.0);
    p.apply(ToUi::TouchTuning(saved));
    p.apply(ToUi::Show(View::Touch));
    let now = Arc::new(AtomicU64::new(1_000_000_000));
    let c = now.clone();
    if let Some(t) = p.ui.get_mut::<TouchTest>(touch_dev::TEST) {
        t.set_clock(Box::new(move || c.load(Ordering::SeqCst)));
    }
    let at = |p: &mut Player, f: u64, ph: Touch, x: i32, y: i32, dt: u64| {
        let t = now.fetch_add(dt, Ordering::SeqCst) + dt;
        p.set_touch_time(t);
        let _ = p.touch(f, ph, x, y);
    };
    let area =
        p.ui.rect_of(touch_dev::TEST)
            .unwrap_or(mpfree_ui::Rect::new(0, 112, 760, 662));
    let (bar, body) = TouchTest::body(area);
    let cells = TouchTest::bar_cells(bar);
    let tap_bar = |p: &mut Player, i: usize| {
        let c = cells[i];
        at(p, 99, Touch::Down, c.x + c.w / 2, c.y + c.h / 2, 300_000);
        at(p, 99, Touch::Up, c.x + c.w / 2, c.y + c.h / 2, 90_000);
    };
    if targets {
        tap_bar(&mut p, 1);
        let area = p.ui.rect_of(touch_dev::TEST).unwrap_or(area);
        let spots = TouchTest::targets(TouchTest::body(area).1);
        for (i, &(x, y)) in spots.iter().take(4).enumerate() {
            let (x, y) = (x + 4 - i as i32 * 2, y - 5 + i as i32);
            at(&mut p, 10 + i as u64, Touch::Down, x, y, 700_000);
            at(&mut p, 10 + i as u64, Touch::Up, x, y, 90_000);
        }
        return p;
    }
    for i in 0..10i32 {
        let (x, y) = (body.x + 80 + (i % 5) * 120, body.y + 120 + (i / 5) * 100);
        at(&mut p, 1, Touch::Down, x, y, 400_000);
        at(&mut p, 1, Touch::Move, x + i % 3, y + 1, 40_000);
        at(
            &mut p,
            1,
            Touch::Up,
            x + i % 3,
            y + 1,
            50_000 + i as u64 * 9_000,
        );
    }
    for i in 0..3i32 {
        let (x, y) = (body.x + 200 + i * 150, body.y + 360);
        at(&mut p, 2, Touch::Down, x, y, 400_000);
        for k in 1..=8 {
            at(
                &mut p,
                2,
                Touch::Move,
                x + [0, 2, 0, -2][k % 4],
                y + [0, 1, 0, -1][(k + 1) % 4],
                110_000,
            );
        }
        at(&mut p, 2, Touch::Up, x, y, 20_000);
    }
    tap_bar(&mut p, 2);
    for i in 0..4i32 {
        let y = body.y + 160 + i * 40;
        at(&mut p, 3, Touch::Down, body.x + 120, y, 500_000);
        for k in 1..=18 {
            at(
                &mut p,
                3,
                Touch::Move,
                body.x + 120 + k * 24,
                y + k / 6,
                9_000,
            );
        }
        at(&mut p, 3, Touch::Up, body.x + 120 + 18 * 24, y + 3, 2_000);
    }
    tap_bar(&mut p, 0);
    // A finger down, dragged in an arc.
    at(&mut p, 4, Touch::Down, body.x + 180, body.y + 300, 400_000);
    for k in 1..=24 {
        let a = k as f32 * 0.09;
        let (x, y) = (
            body.x + 180 + (a.sin() * 220.0) as i32,
            body.y + 300 - ((1.0 - a.cos()) * 140.0) as i32,
        );
        at(&mut p, 4, Touch::Move, x, y, 9_000);
    }
    p.apply(ToUi::TouchWheel(5));
    p
}

pub fn apply_effects(p: &mut Player, fx: Vec<crate::app::Effect>) {
    use crate::app::Effect;
    for e in fx {
        match e {
            Effect::Show(v) => p.apply(ToUi::Show(v)),
            Effect::Menu(m) => p.apply(ToUi::Menu(m)),
            Effect::Guide(g) => p.apply(ToUi::Guide(g)),
            Effect::Status(s) => p.apply(ToUi::Status(s)),
            Effect::Settings(s) => p.apply(ToUi::Settings(s)),
            Effect::Arp(v) => p.apply(ToUi::Arp(Box::new(v))),
            Effect::SixteenLevels => p.apply(ToUi::SixteenLevels),
            Effect::LevelsWheel(d) => p.apply(ToUi::LevelsWheel(d)),
            Effect::Steps(_) => {}
            Effect::Patterns(l) => p.apply(ToUi::Patterns(l)),
            Effect::Workspace(w) => p.apply(ToUi::Workspace(Box::new(w))),
            Effect::Recorded(pat, next) => p.apply(ToUi::Recorded(Box::new(pat), next)),
            Effect::WorkspaceWheel(d) => p.apply(ToUi::WorkspaceWheel(d)),
            Effect::ClearLogs => p.apply(ToUi::ClearLogs),
            Effect::ClearConsole => p.apply(ToUi::ClearConsole),
            Effect::TouchLab => p.apply(ToUi::TouchLab),
            Effect::CalibrateTouch => p.apply(ToUi::CalibrateTouch),
            Effect::TouchWheel(d) => p.apply(ToUi::TouchWheel(d)),
            Effect::TouchStep(d) => p.apply(ToUi::TouchStep(d)),
            Effect::Note(l) => p.apply(ToUi::Line(l)),
            Effect::Tell(l) => {
                p.apply(ToUi::Line(l.clone()));
                p.apply(ToUi::Tell(l));
            }
            Effect::Undo { redo } => p.apply(ToUi::Undo(redo)),
            Effect::UndoButton(down) => p.apply(ToUi::UndoButton(down)),
            // The desk carries it out (the transport and the looper).
            Effect::Rec(_) | Effect::PadRec(_) | Effect::PadArm { .. } => {}
            Effect::PadTake(d) => p.apply(ToUi::PadTake(d)),
            Effect::Recall(k) => p.apply(ToUi::Recall(k)),
            Effect::Nav(n) => p.apply(ToUi::Nav(n)),
            Effect::Held { delta, fine } => p.apply(ToUi::Held { delta, fine }),
            Effect::ClipsWheel { delta, scroll } => p.apply(ToUi::ClipsWheel { delta, scroll }),
            Effect::Map(m) => p.apply(ToUi::Map(Box::new(m))),
            Effect::SynthPage(d) => p.apply(ToUi::SynthPage(d)),
            Effect::SampleWheel(d) => p.apply(ToUi::SampleWheel(d)),
            Effect::Rows(k) => p.apply(ToUi::Rows(k)),
            Effect::SamplePad(d) => p.apply(ToUi::SamplePad(d)),
            Effect::SampleUndo { redo } => p.apply(ToUi::SampleUndo(redo)),
            Effect::PlayView(v) => p.apply(ToUi::PlayView(v)),
            Effect::ArrangeView(v) => p.apply(ToUi::ArrangeView(v)),
            Effect::SampleEditor(e) => p.apply(ToUi::SampleEditor(e)),
            Effect::EditPad => p.apply(ToUi::EditPad),
            Effect::Browse(k) => p.apply(ToUi::Browse(k)),
            Effect::SaveProject => p.ask_save(),
            Effect::PerformSet { set, opened } => p.apply(ToUi::PerformSet { set, opened }),
            Effect::SynthPick(v) => p.apply(ToUi::SynthPick(v.map(Box::new))),
            Effect::PadsFocus(f) => p.apply(ToUi::PadsFocus(f)),
            Effect::Light(..)
            | Effect::StopSounds
            | Effect::Audio(_)
            | Effect::Quit
            | Effect::Time(_)
            | Effect::Octave(_)
            | Effect::Bank { .. }
            | Effect::BankLights
            | Effect::Looper(_)
            | Effect::PlayFx(_)
            | Effect::TrackMute { .. }
            | Effect::SavePatterns(_)
            | Effect::SynthPads(_)
            | Effect::TrackSound { .. }
            | Effect::TrackSend { .. }
            | Effect::TrackCopy { .. }
            | Effect::SynthOnTrack(_)
            | Effect::ProgEdit
            | Effect::Metronome { .. }
            | Effect::Fill(_)
            | Effect::Mixer(_)
            | Effect::MixerLast
            | Effect::SetupNextStart { .. } => {}
            Effect::MixerFaders => p.apply(ToUi::MixerFaders),
            Effect::MixerWheel(d) => p.apply(if p.io_showing() {
                ToUi::IoInput(mpfree_mixer_ui::IoInput::Wheel(d))
            } else {
                ToUi::MixerQLink(0, d)
            }),
            Effect::MixerStep(d) => {
                if p.io_showing() {
                    p.apply(ToUi::IoInput(mpfree_mixer_ui::IoInput::Step(d)));
                }
            }
            Effect::ChainTurn { knob, delta } => p.apply(ToUi::ChainQLink(knob, delta)),
            Effect::ChainWheel(d) => p.apply(ToUi::ChainWheel(d)),
            Effect::ChainPush => p.apply(ToUi::ChainPush),
            Effect::QLinkBank => p.apply(ToUi::QLinkBank),
            Effect::QLinkBankBack => p.apply(ToUi::QLinkBankBack),
            Effect::PadCopy { from, to } => p.apply(ToUi::PadCopy { from, to }),
            Effect::PadClear { pad } => p.apply(ToUi::PadClear(pad)),
            Effect::PadPick { slot } => p.apply(ToUi::PadPick(usize::from(slot))),
            Effect::TypeTempo => p.apply(ToUi::TypeTempo),
            Effect::ControllerSettings => p.apply(ToUi::OpenIoSection(mpfree_midi_ui::CONTROLLER)),
            Effect::ScreenPicture => p.apply(ToUi::ScreenPicture),
            Effect::XyFull => p.apply(ToUi::XyFull),
            Effect::Reset => p.apply(ToUi::Reset),
            // The time engine's and the mod panels': no screen of their own.
            Effect::RecordQuantiseToggle
            | Effect::PlayBack
            | Effect::CountInToggle
            | Effect::MacrosPanel => {}
        }
    }
}

/// The app's arp, run for `frames` frames, and its view on the screen.
fn run_arp(p: &mut Player, app: &mut crate::app::App, frames: u32) {
    let mut ev = mpfree_arp::Events::new();
    for _ in 0..frames / 128 {
        app.process(128, &mut ev);
    }
    let fx: Vec<_> = app.arp_poll().into_iter().collect();
    apply_effects(p, fx);
}

/// The sample player with no pad held or fading, for the arp's screens.
fn quiet_player(fonts: Fonts) -> Player {
    let mut p = sample_player(fonts);
    if let Some(g) =
        p.ui.get_mut::<MiniPads>(play_page::PADS)
            .map(|m| &mut m.grid)
    {
        for pad in g.pads.iter_mut() {
            pad.held = false;
            pad.level = 0.0;
        }
    }
    p
}

/// The Arrange page with the real time engine behind it: tapping Track 1's
/// first slot recorded a two-bar beat from the pads (kick, snare, hats),
/// REC punched out at bar 3, the clip plays on at 3.2, and Track 2 is
/// armed for the next one.
pub fn sample_clips(fonts: Fonts) -> Result<Player, String> {
    use crate::time::{Pads, TimeHost};
    use mpfree_play::Event;
    struct Silent;
    impl Pads for Silent {
        fn hit_at(&mut self, _track: u16, _pad: usize, _velocity: u8, _offset: u32) -> bool {
            true
        }
        fn release_at(&mut self, _track: u16, _pad: usize, _offset: u32) {}
        fn stop_all(&mut self) {}
        fn pressure_at(&mut self, _track: u16, _pad: usize, _value: u8, _offset: u32) {}
    }
    const RATE: u32 = 44_100;
    const PERIOD: u32 = 128;
    const BAR: i64 = 4 * 960;
    let mut host = TimeHost::new(RATE, 120.0)?;
    host.act(TimeAction::NewClip { track: 0, slot: 0 })?;
    // (song tick, pad, velocity): kick on 1 and 3 (and the "and" of 3),
    // snare on 2 and 4, closed hat on every eighth; twice.
    let mut hits = Vec::new();
    for bar in 0..2 {
        for (tick, pad, velocity) in [
            (0, 0, 118),
            (1920, 0, 104),
            (2400, 0, 90),
            (960, 1, 112),
            (2880, 1, 116),
        ] {
            hits.push((bar * BAR + tick, pad, velocity));
        }
        for eighth in 0..8 {
            hits.push((
                bar * BAR + eighth * 480,
                2,
                if eighth % 2 == 0 { 96 } else { 70 },
            ));
        }
    }
    let mut notes: Vec<(i64, Event)> = hits
        .iter()
        .flat_map(|&(t, pad, velocity)| {
            [
                (
                    t,
                    Event::NoteOn {
                        note: pad,
                        velocity,
                    },
                ),
                (t + 120, Event::NoteOff { note: pad }),
            ]
        })
        .collect();
    notes.sort_by_key(|n| n.0);
    let ticks_per_frame = 960.0 * 120.0 / 60.0 / f64::from(RATE);
    let mut next = 0;
    let mut run_to = |host: &mut TimeHost, end: i64| -> Result<(), String> {
        for _ in 0..100_000 {
            let at = host.info().position;
            if at >= end {
                return Ok(());
            }
            let period_end = at as f64 + f64::from(PERIOD) * ticks_per_frame;
            while next < notes.len() && (notes[next].0 as f64) < period_end {
                let offset = ((notes[next].0 - at).max(0) as f64 / ticks_per_frame) as u32;
                host.pad(offset.min(PERIOD - 1), notes[next].1);
                next += 1;
            }
            host.period(PERIOD, &mut Silent);
        }
        Err(format!("the sample never reached tick {end}"))
    };
    // The first period starts recording at bar 1.
    run_to(&mut host, 2 * BAR - 120)?;
    host.act(TimeAction::Transport(mpfree_transport::Command::Record))?;
    run_to(&mut host, 2 * BAR + 960 + 240)?;
    host.act(TimeAction::Arm(Some(1)))?;
    run_to(&mut host, 2 * BAR + 960 + 300)?;
    let mut p = quiet_player(fonts);
    p.apply(ToUi::Time(Box::new(host.state())));
    p.apply(ToUi::Show(View::Arrange));
    Ok(p)
}

/// The Arrange page in the middle of a jam (Jay, 19 Nov 02:45Z: more
/// clips, in more states, some slots empty): the time UI's busy session
/// (six tracks playing, Vox chop recording, two launches waiting for the
/// bar), Keys on Poly, Lead on FM and Chords on Strings, and Loops A's
/// cells drawn from the busy looper's own loops.
pub fn sample_clips_busy(fonts: Fonts) -> Result<Player, String> {
    let s = mpfree_time_ui::sample::busy_playing()?;
    let mut p = quiet_player(fonts);
    busy_sounds(&mut p);
    p.apply(ToUi::Time(Box::new(s.state())));
    p.apply(ToUi::Show(View::Arrange));
    Ok(p)
}

/// The busy jam's loops and synths: the looper's six loops, and Keys,
/// Lead and Chords (tracks 4-6) on Poly, FM and Strings.
fn busy_sounds(p: &mut Player) {
    p.apply(ToUi::Looper(Box::new(busy_loops().clone())));
    let mut sounds: TrackSounds = [None; crate::instruments::HOLDERS];
    for (t, id, name) in [
        (3, "mpfree.poly", "Poly"),
        (4, "mpfree.fm", "FM"),
        (5, "mpfree.strings", "Strings"),
    ] {
        sounds[t] = Some(crate::instruments::Held {
            id,
            name,
            instance: 0,
        });
    }
    p.apply(ToUi::TrackSounds(Box::new(sounds)));
}

/// The pad player on the Sample page: kit 1's pad 5 holds the sampler UI's
/// made-up drum loop ("Break 92", trimmed, looping, with fades), and a voice
/// is playing it. Kit 1's other pads are empty here.
/// The Pads tab's pads, as a tap on its tab would show them (from Edit
/// pad too: a tap on the tab goes back to the pads).
pub fn open_pads(p: &mut Player) {
    if p.view == View::Pads && p.sample.edit_pad_on() {
        p.sample.open_editor(&mut p.ui, sample_page::Editor::Pads);
    }
    p.apply(ToUi::Show(View::Pads));
}

/// The Pads tab with a pad of each type, each made with the type switch
/// (the redesign's board 6): A5 a loop, A11 a voice of the Synth tab's
/// Poly, A13 a MIDI out pad sending to a Volca Kick plugged in, picked.
#[inline(never)]
fn pads_types(fonts: Fonts) -> Player {
    use mpfree_sampler_ui::pads_tab::PadType;
    pads_typed(
        fonts,
        &[
            (mpfree_sampler_ui::sample::PAD, PadType::Loop),
            (10, PadType::Instrument),
            (12, PadType::MidiOut),
        ],
    )
}

/// The Pads tab on a full kit ([`mpfree_sampler_ui::sample::full_kit_project`]):
/// A1-A8 one-shot samples, A9-A16 loops, synth voices and MIDI out to a
/// Volca Kick and a Juno-X, banks B to F partly filled; A5's snare picked,
/// with a compressor on its channel.
#[inline(never)]
fn pads_full(fonts: Fonts) -> Player {
    use mpfree_sampler_ui::pads_tab;
    use mpfree_sampler_ui::sample::{full_kit_project, PAD, RATE};
    let mut p = sample_player(fonts);
    let port = |name: &str| mpfree_midi_ui::PortLive {
        name: name.into(),
        kind: "USB".into(),
        about: "USB".into(),
        has_in: false,
        has_out: true,
        sending: true,
        last_in: None,
        clock_measured: None,
    };
    let mut m = mpfree_midi_ui::IoModel::default();
    m.live.built.notes_out = true;
    m.live.ports = vec![port("Volca Kick"), port("Juno-X")];
    p.apply(ToUi::IoModel(std::sync::Arc::new(std::sync::Mutex::new(m))));
    let project = full_kit_project();
    let mut kits = p.kits.clone();
    kits[0].name = "Breaks".to_string();
    kits[0].pads = (0..16)
        .map(|i| project.pad(i).map(|pad| pad.name.clone()))
        .collect();
    p.apply(ToUi::Kits(kits));
    p.apply(ToUi::SampleKits {
        projects: vec![project],
        rate: RATE,
    });
    open_pads(&mut p);
    p.on_event(UiEvent {
        widget: pads_tab::MAP.into(),
        kind: EventKind::Select(PAD),
    });
    p.apply(ToUi::PadFx(
        (0..crate::mixing::PADS)
            .map(|i| {
                let fx = if i == PAD {
                    vec!["Compressor".to_string()]
                } else {
                    Vec::new()
                };
                (0, i, fx)
            })
            .collect(),
    ));
    sample_kit_tracks(&mut p);
    let _ = p.take_actions();
    p.tick(30.0);
    p
}

/// Play's rows with a pad of each type (the redesign's board 2): kit 1
/// on track 1, swiped down to A5-A10. A5 loops "Break 92", A6 is a Poly
/// voice, A8 sends to a Volca Kick, and A7, A9 and A10 are empty.
#[inline(never)]
fn play_pad_types(fonts: Fonts) -> Player {
    use mpfree_sampler_ui::pads_tab::PadType;
    let mut p = pads_typed(
        fonts,
        &[
            (mpfree_sampler_ui::sample::PAD, PadType::Loop),
            (5, PadType::Instrument),
            (7, PadType::MidiOut),
        ],
    );
    p.apply(ToUi::Show(View::Play));
    p.on_event(UiEvent {
        widget: play_page::STEPS.into(),
        kind: EventKind::Step {
            index: play_widgets::ROWS,
            delta: 4,
        },
    });
    let _ = p.take_actions();
    p
}

/// The Pads tab's Perform view (the redesign's board 7): page B, Play's
/// throws on pads 1 to 8 (Vinyl brake latched), two track mutes, Loop 2's
/// key and a scene over them, and two throws on the drums alone (Delay
/// throw on the Drums track, Beat repeat on Sub 1); Reverb wash on B2
/// picked.
#[inline(never)]
fn pads_perform(fonts: Fonts) -> Player {
    use crate::perform_pads::{Hold, PadAction, PerformSet, Throw};
    let mut p = sample_sampler(fonts);
    open_pads(&mut p);
    sample_kit_tracks(&mut p);
    let mut set = PerformSet::default();
    let b = &mut set.pages[1].pads;
    b[6] = PadAction::Macro {
        card: 0,
        value: 100,
    };
    b[7] = PadAction::Throw(Throw::new(7, Hold::Latch));
    b[8] = PadAction::Mute(0);
    b[9] = PadAction::Mute(1);
    b[10] = PadAction::LoopKey(1);
    b[11] = PadAction::Scene(1);
    // Two throws on the drums alone: Delay throw on the Drums track, and
    // Beat repeat on Sub 1.
    let on = |index, on| {
        PadAction::Throw(Throw {
            on,
            ..Throw::new(index, Hold::WhileHeld)
        })
    };
    b[12] = on(0, mpfree_fx::StripId::Track(0));
    b[13] = on(5, mpfree_fx::StripId::Bus(0));
    p.apply(ToUi::PerformSet {
        set: Box::new(set),
        opened: true,
    });
    let mut strips: Vec<(String, mpfree_fx::StripId)> =
        ["Master", "Drums", "Synth", "Loop", "Audio"]
            .iter()
            .zip([
                mpfree_fx::StripId::Master,
                mpfree_fx::StripId::Track(0),
                mpfree_fx::StripId::Track(1),
                mpfree_fx::StripId::Track(2),
                mpfree_fx::StripId::Track(3),
            ])
            .map(|(n, s)| (n.to_string(), s))
            .collect();
    strips.extend((0..8).map(|b| (format!("Sub {}", b + 1), mpfree_fx::StripId::Bus(b))));
    p.apply(ToUi::ThrowStrips(strips));
    p.apply(ToUi::ThrowKnobs(sample_throw_knobs(&p.perform.set)));
    p.on_event(UiEvent {
        widget: mpfree_sampler_ui::pads_tab::KITS.into(),
        kind: EventKind::Tab(1),
    });
    let mut s = p.status.clone();
    s.perform_bank = 1;
    p.apply(ToUi::Status(s));
    p.on_event(UiEvent {
        widget: crate::perform_tab::MAP.into(),
        kind: EventKind::Select(1),
    });
    let _ = p.take_actions();
    p
}

/// Each throw of `set` with the Perform FX's own settings for it (its
/// default bank), as the app sends them once the strips have their Perform
/// FX.
fn sample_throw_knobs(set: &crate::perform_pads::PerformSet) -> Vec<crate::mixing::ThrowKnobs> {
    use crate::perform_pads::PadAction;
    use mpfree_fx::ids::perform as pf;
    use mpfree_node::Node;
    let node = mpfree_fx::Perform::new();
    let mut out: Vec<crate::mixing::ThrowKnobs> = Vec::new();
    for a in set.pages.iter().flat_map(|p| p.pads.iter()) {
        let PadAction::Throw(t) = *a else { continue };
        let Some(fx) = t.fx() else { continue };
        if out.iter().any(|k| k.on == t.on && k.fx == fx) {
            continue;
        }
        let v = |o: u16| node.param(pf::slot(fx.pad()) + o);
        out.push(crate::mixing::ThrowKnobs {
            on: t.on,
            fx,
            uid: Some(1),
            effect: v(pf::EFFECT) as u8,
            length: v(pf::LENGTH),
            amount: v(pf::AMOUNT),
        });
    }
    out
}

/// The Perform view on B13, the Delay throw on Drums: Q1 and Q2 its Time
/// and Feedback on the Drums track's Perform FX, Q2 turned.
fn pads_perform_knobs(fonts: Fonts) -> Player {
    let mut p = pads_perform(fonts);
    p.on_event(UiEvent {
        widget: crate::perform_tab::MAP.into(),
        kind: EventKind::Select(12),
    });
    p.apply(ToUi::SampleQLink(1, 7));
    p.apply(ToUi::QLinkTouch(1, true));
    let _ = p.take_actions();
    p
}

/// The Pads tab with `picks`' pads made each type with the type switch, a
/// Volca Kick plugged in for MIDI out; the last one picked.
fn pads_typed(fonts: Fonts, picks: &[(usize, mpfree_sampler_ui::pads_tab::PadType)]) -> Player {
    use mpfree_sampler_ui::pads_tab::{self, PadType};
    let mut p = sample_sampler(fonts);
    let mut m = mpfree_midi_ui::IoModel::default();
    m.live.built.notes_out = true;
    m.live.ports = vec![mpfree_midi_ui::PortLive {
        name: "Volca Kick".into(),
        kind: "USB".into(),
        about: "USB".into(),
        has_in: false,
        has_out: true,
        sending: true,
        last_in: None,
        clock_measured: None,
    }];
    p.apply(ToUi::IoModel(std::sync::Arc::new(std::sync::Mutex::new(m))));
    open_pads(&mut p);
    for &(pad, t) in picks {
        p.on_event(UiEvent {
            widget: pads_tab::MAP.into(),
            kind: EventKind::Select(pad),
        });
        let i = PadType::ALL.iter().position(|x| *x == t).unwrap_or(0);
        p.on_event(UiEvent {
            widget: pads_tab::TYPE.into(),
            kind: EventKind::Tab(i),
        });
    }
    sample_kit_tracks(&mut p);
    let _ = p.take_actions();
    // What the last switch did has been read: the hint is back.
    p.tick(30.0);
    p
}

