/// Opens the Sample tab's Play section that holds `row` (a tap on its
/// chip) and gives the row's place in that section's list.
pub fn play_row(p: &mut Player, row: mpfree_sampler_ui::play_tab::Row) -> usize {
    use mpfree_sampler_ui::play_tab::{Section, SECTIONS};
    let i = Section::ALL
        .iter()
        .position(|s| *s == row.section())
        .unwrap_or(0);
    p.on_event(UiEvent {
        widget: SECTIONS.into(),
        kind: EventKind::Tab(i),
    });
    row.place()
}

pub fn sample_sampler(fonts: Fonts) -> Player {
    let mut p = sample_player(fonts);
    let (project, _) = mpfree_sampler_ui::sample::project();
    let pad = mpfree_sampler_ui::sample::PAD;
    let mut kits = p.kits.clone();
    kits[0].name = "Breaks".to_string();
    kits[0].pads = (0..16)
        .map(|i| (i == pad).then(|| "Break 92".to_string()))
        .collect();
    p.apply(ToUi::Kits(kits));
    p.apply(ToUi::SampleKits {
        projects: vec![project],
        rate: mpfree_sampler_ui::sample::RATE,
    });
    p.apply(ToUi::PadDown { pad, velocity: 100 });
    p.apply(ToUi::PadUp(pad));
    p.apply(ToUi::Show(View::Sample));
    settle_views(&mut p);
    let beat = f64::from(mpfree_sampler_ui::sample::RATE) * 60.0 / mpfree_sampler_ui::sample::BPM;
    let mut heads = Playheads {
        kit: 0,
        len: 1,
        ..Playheads::default()
    };
    heads.pad[0] = pad as u8;
    heads.frame[0] = (beat * 4.6) as u32;
    p.apply(ToUi::SamplePlayheads(heads));
    p
}

/// [`sample_sampler`] with an empty user kit after the six (before the
/// synth's), its sounds on the Sample page too, so Chop can put slices on
/// a new kit (sampler R4.6). Returns the player and the empty kit.
pub fn sample_sampler_with_empty_kit(fonts: Fonts) -> (Player, usize) {
    let mut p = sample_player(fonts);
    let (project, _) = mpfree_sampler_ui::sample::project();
    let pad = mpfree_sampler_ui::sample::PAD;
    let synth = crate::synth::Synth::new(44_100);
    let mut kits: Vec<KitView> = p
        .kits
        .iter()
        .filter(|k| k.synth.is_none())
        .cloned()
        .collect();
    kits[0].name = "Breaks".to_string();
    kits[0].pads = (0..16)
        .map(|i| (i == pad).then(|| "Break 92".to_string()))
        .collect();
    let u = kits.len();
    kits.push(KitView {
        name: format!("Kit {}", u + 1),
        pads: vec![None; 128],
        colour: [0x10, 0x10, 0x10],
        chip: None,
        synth: None,
        pitches: Vec::new(),
        user: true,
        key: None,
        tags: Vec::new(),
    });
    kits.push(synth.kit_view());
    p.apply(ToUi::Kits(kits));
    let mut projects = vec![project];
    projects.resize_with(u + 1, mpfree_sampler::model::Project::new);
    p.apply(ToUi::SampleKits {
        projects,
        rate: mpfree_sampler_ui::sample::RATE,
    });
    p.apply(ToUi::PadDown { pad, velocity: 100 });
    p.apply(ToUi::PadUp(pad));
    p.apply(ToUi::Show(View::Sample));
    settle_views(&mut p);
    (p, u)
}

/// How long the screens and tests wait for the Sample tab's worker threads
/// (the analysis, a load, a process). Under a second on its own, but a
/// coverage build on a busy CI runner took over 10 s for one sound's
/// analysis, so the wait is long, and running out of it is a failure that
/// says so, never a screen or a test going on with half a sound.
pub const WORKER_WAIT: Duration = Duration::from_secs(120);

/// Waits for the Sample tab's sounds to be analysed off the screen thread,
/// as the screen does a moment after a sound is shown. Panics if they still
/// aren't after [`WORKER_WAIT`].
pub fn settle_views(p: &mut Player) {
    let end = Instant::now() + WORKER_WAIT;
    while p.sample.analysing() {
        assert!(
            Instant::now() < end,
            "the Sample tab's sounds were still being analysed after {WORKER_WAIT:?}"
        );
        std::thread::sleep(Duration::from_millis(2));
        p.tick(0.0);
    }
}

