/// The Looper tab mid-jam, for the "looper" screen (Jay, 19 Nov 02:45Z):
/// loop 1 picked with its layers, the busy looper's loops beside it (three
/// playing, two muted, one recording, two empty), and the song playing.
/// The tests keep [`sample_looper`]'s two loops.
fn sample_looper_jam(fonts: Fonts) -> Result<Player, String> {
    looper_screen(fonts, 0, true)
}

/// [`sample_looper_picking`], or with `jam` [`sample_looper_jam`].
fn looper_screen(fonts: Fonts, picked: usize, jam: bool) -> Result<Player, String> {
    use crate::looping::{LoopHost, PERIOD};
    use mpfree_looper::{Command as L, Phase};
    use mpfree_transport::{Block, Command as T, Transport};
    const RATE: u32 = 44_100;
    let mut p = sample_player(fonts);
    p.apply(ToUi::Show(View::Looper));
    // (The tab arming the loop, for a desk there is none of here.)
    p.take_actions();
    // Loop 2, on a looper of its own (the view takes its line).
    let mut h = LoopHost::new(RATE, 20);
    let mut t = Transport::new(RATE, 92.0).map_err(|e| format!("{e:?}"))?;
    let mut b = Block::new();
    h.select(1);
    h.command(L::SetBars(Some(2)));
    h.command(L::SetLatency(0));
    h.command(L::Record);
    t.command(0, T::Play);
    let beat = (f64::from(RATE) * 60.0 / 92.0) as u64;
    let len = 8 * beat;
    for i in 0..(len + len / 8) / PERIOD as u64 {
        if i == len / PERIOD as u64 {
            h.command(L::Mute(true));
        }
        if !t.process(PERIOD as u32, &mut b) {
            return Err("the transport refused a period".into());
        }
        let (mut l, mut r) = ([0.0f32; PERIOD], [0.0f32; PERIOD]);
        for f in 0..PERIOD {
            let n = i * PERIOD as u64 + f as u64;
            let half = (n % (beat / 2)) as f32 / RATE as f32;
            let noise = ((n.wrapping_mul(2_654_435_761) >> 7) % 2000) as f32 / 1000.0 - 1.0;
            let v = noise * (-half * 50.0).exp() * 0.3;
            (l[f], r[f]) = (v, v);
        }
        h.take_pads(&l, &r);
        h.period(&b, &mut l, &mut r);
        h.changes(String::new);
    }
    let second = h.view(92.0);
    if second.loops[1].phase != Phase::Playing || !second.loops[1].muted {
        return Err(format!("loop 2 is {:?}", second.loops[1].phase));
    }
    // Loop 1 and its layers, as the Play page's previews have them.
    let (wave, view) = recorded_loop();
    // The jam: three playing, two muted, one recording, two empty.
    let mut v = if jam {
        busy_loops().clone()
    } else {
        let mut v = view.clone();
        v.loops[1] = second.loops[1];
        v.memory.used += second.memory.used;
        v
    };
    // The memory the app gives the loops (Prefs "Loop memory" as it starts).
    v.memory.capacity = crate::looping::LoopMemory::default().seconds() as usize * RATE as usize;
    v.meter_db = [-6.5, -6.5];
    if let Some(l) = v.layers[2].as_mut() {
        l.muted = true;
        l.audible = false;
    }
    if let Some(l) = v.layers[1].as_mut() {
        l.level = 10f32.powf(-3.5 / 20.0);
        l.pan = -0.24;
    }
    if let Some(l) = v.layers[2].as_mut() {
        l.level = 10f32.powf(-6.0 / 20.0);
    }
    if picked > 1 {
        v.selected = picked;
        v.status = v.loops[picked];
        v.layers = [None; mpfree_looper::MAX_LAYERS];
        v.capture_into = Some((picked, 2));
    }
    if jam {
        // The jam is running: bar 9 at the Play page's 92 BPM.
        p.apply(ToUi::Transport(TransportInfo {
            state: mpfree_transport::State::Playing,
            position: 8 * mpfree_transport::time::PPQ as i64 * 4,
            bpm: 92.0,
            ..TransportInfo::default()
        }));
    }
    p.apply(ToUi::Looper(Box::new(v)));
    p.looper_page.set_names(&["Drums", "Bass", "Chop"]);
    if picked <= 1 {
        p.apply(ToUi::LoopWave(Arc::clone(wave)));
        p.looper_page.pick_layer(&mut p.ui, 1);
    }
    Ok(p)
}

/// The chain editor (`View::Chain`) or the macros panel (`View::Macros`)
/// with the chain-ui crate's sample song: the drum bus chain, Drive
/// selected and its Tone touched, as the audio thread sends them.
fn sample_panels(p: &mut Player, view: View) {
    use mpfree_chain_ui::sample::{Song, DRUMS};
    use mpfree_play::mpfree_param::Owner;
    let song = Song::new();
    p.apply(ToUi::Show(view));
    if view == View::Chain {
        let tone = song
            .drums
            .uid(1)
            .map(|uid| ParamAddr::new(Owner::Insert(DRUMS, uid), mpfree_fx::ids::drive::TONE));
        let mut st = song.chain_state(DRUMS, 1, 0, tone);
        st.back = Some("Mixer".into());
        // The strip button, as the app fills it (`ChainHost::state`).
        st.strip_name = st.title.trim_end_matches(" FX").to_string();
        st.strip_kind = "Track 1".into();
        let fx = song
            .chain(DRUMS)
            .node(1)
            .map(|n| Box::new(FxState::from_node(n, "", Color::rgb(0), 120.0, 44_100)));
        p.apply(ToUi::Chain(Box::new(st)));
        p.apply(ToUi::ChainFx(fx));
    }
    p.apply(ToUi::Macros(Box::new(song.macros_state(0))));
}

/// The chain editor on the drum bus's EQ, shaped as on the approved
/// mockups (a low cut, a low bump, a mud cut on band 2, presence and a
/// high cut), band 2 picked, as the app sends it.
fn sample_eq_page(p: &mut Player) -> Result<(), String> {
    use mpfree_chain_ui::sample::{Song, DRUMS};
    use mpfree_fx::ids::eq as q;
    use mpfree_play::mpfree_param::Owner;
    let mut song = Song::new();
    {
        let e = song.drums.node_mut(3).ok_or("the drum bus EQ")?;
        for (id, v) in [
            (q::LOW_CUT, 35.0),
            (q::LOW_SLOPE, 1.0),
            (q::HIGH_CUT, 9_000.0),
            (q::HIGH_SLOPE, 1.0),
            (q::band_type(0), 0.0),
            (q::freq(0), 90.0),
            (q::gain(0), 3.0),
            (q::q(0), 1.0),
            (q::band_type(1), 0.0),
            (q::freq(1), 320.0),
            (q::gain(1), -3.5),
            (q::q(1), 1.4),
            (q::band_type(2), 0.0),
            (q::freq(2), 1_200.0),
            (q::gain(2), 2.0),
            (q::q(2), 2.0),
            (q::band_use(3), q::USE_UNUSED),
        ] {
            e.set_param(id, v);
        }
    }
    let uid = song.drums.uid(3).ok_or("the drum bus EQ")?;
    let mud = ParamAddr::new(Owner::Insert(DRUMS, uid), q::gain(1));
    p.apply(ToUi::Show(View::Chain));
    let mut st = song.chain_state(DRUMS, 3, 0, Some(mud));
    st.back = Some("Mixer".into());
    st.strip_name = st.title.trim_end_matches(" FX").to_string();
    st.strip_kind = "Track 1".into();
    let fx = song
        .chain(DRUMS)
        .node(3)
        .map(|n| Box::new(FxState::from_node(n, "", Color::rgb(0), 120.0, 44_100)));
    p.apply(ToUi::Chain(Box::new(st)));
    p.apply(ToUi::ChainFx(fx));
    p.apply(ToUi::Macros(Box::new(song.macros_state(0))));
    Ok(())
}

/// The Compressor's page in the chain editor: the drum bus's slot 3 glueing
/// the kit (Bus style, 4:1, RMS, auto makeup), Ratio touched. Its
/// Reduction meter reads what a bar of drums at this setting takes,
/// as the engine's meter would mid-bar (no audio runs in a preview).
fn sample_comp_page(p: &mut Player) -> Result<(), String> {
    use mpfree_chain_ui::sample::{Song, DRUMS};
    use mpfree_fx::ids::compressor as c;
    use mpfree_play::mpfree_param::Owner;
    const SLOT: usize = 2;
    let mut song = Song::new();
    {
        let e = song.drums.node_mut(SLOT).ok_or("the drum bus Compressor")?;
        for (id, v) in [
            (c::STYLE, c::BUS),
            (c::THRESHOLD, -22.0),
            (c::RATIO, 4.0),
            (c::ATTACK, 10.0),
            (c::RELEASE, 120.0),
            (c::KNEE, 6.0),
            (c::DETECT, 1.0),
            (c::AUTO_MAKEUP, 1.0),
            (c::SC_FILTER, 90.0),
            (c::MIX, 80.0),
        ] {
            e.set_param(id, v);
        }
    }
    let uid = song.drums.uid(SLOT).ok_or("the drum bus Compressor")?;
    let ratio = ParamAddr::new(Owner::Insert(DRUMS, uid), c::RATIO);
    p.apply(ToUi::Show(View::Chain));
    let mut st = song.chain_state(DRUMS, SLOT, 0, Some(ratio));
    st.back = Some("Mixer".into());
    st.strip_name = st.title.trim_end_matches(" FX").to_string();
    st.strip_kind = "Track 1".into();
    for v in st
        .params
        .iter_mut()
        .filter(|v| v.addr.param == c::REDUCTION)
    {
        v.value = -4.5;
        v.pos = (v.value - v.info.min) / (v.info.max - v.info.min);
    }
    let fx = song
        .chain(DRUMS)
        .node(SLOT)
        .map(|n| Box::new(FxState::from_node(n, "", Color::rgb(0), 92.0, 44_100)));
    p.apply(ToUi::Chain(Box::new(st)));
    p.apply(ToUi::ChainFx(fx));
    p.apply(ToUi::Macros(Box::new(song.macros_state(0))));
    Ok(())
}

/// The chain editor on the keys' Compressor, listening to the kick pad
/// (layout spec 4b, "Sidechain"), with `list` the sidechain list over it,
/// as the app sends them.
fn sample_sidechain(p: &mut Player, list: bool) -> Result<(), String> {
    let (song, st) = mpfree_chain_ui::sample::sidechain_example(list)?;
    p.apply(ToUi::Show(View::Chain));
    let fx = st
        .selected
        .and_then(|slot| song.keys.node(slot))
        .map(|n| Box::new(FxState::from_node(n, "", Color::rgb(0), 120.0, 44_100)));
    p.apply(ToUi::Chain(Box::new(st)));
    p.apply(ToUi::ChainFx(fx));
    p.apply(ToUi::Macros(Box::new(song.macros_state(0))));
    Ok(())
}

/// The chain editor on a note track (layout spec 4b, board 7): NOTES above
/// SOUND, the Chord picked, its settings on the Q-Links, as the app sends
/// them (`ChainHost::dress_notes`).
fn sample_notes(p: &mut Player) {
    use mpfree_chain_ui::sample::{Song, KEYS};
    let song = Song::new();
    p.apply(ToUi::Show(View::Chain));
    let mut st = song.chain_state(KEYS, 0, 0, None).without_page();
    st.back = Some("Mixer".into());
    st.strip_name = st.title.trim_end_matches(" FX").to_string();
    st.strip_kind = "Track 5".into();
    let mut ns = mpfree_chain_ui::notes::example();
    ns.track = 4;
    if let Some((_, id, fx)) = ns.page_fx() {
        (st.params, st.main_four) = mpfree_chain_ui::notes::param_views(ns.track, id, &fx);
    }
    st.notes = Some(ns);
    p.apply(ToUi::Chain(Box::new(st)));
    p.apply(ToUi::ChainFx(None));
    p.apply(ToUi::Macros(Box::new(song.macros_state(0))));
}

/// The browser over the page, opened from the Pads tab's Browse for A5,
/// in Samples / Drums with Kick 01 picked: Load on A5 and Next pad hit.
/// Over a library filled in a scratch folder (removed again once the
/// browser has read what it shows).
fn browser_samples(fonts: Fonts) -> Result<Player, String> {
    use mpfree_browser_ui::sample::{fill, open, select, source};
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let dir = std::env::temp_dir().join(format!(
        "mpfree-browser-samples-{}-{nanos}",
        std::process::id()
    ));
    let built = (|| {
        std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        let lib = fill(&dir)?;
        let mut p = sample_sampler(fonts);
        p.set_browser(
            mpfree_browser_ui::Browser::inline(lib),
            "recent = Samples/Drums/Kick 01.wav\nfavourite = Samples/Drums/Snare tight.wav\n",
        );
        sample_kit_tracks(&mut p);
        open_pads(&mut p);
        p.apply(ToUi::Show(View::Browser));
        let b = p.browser.as_mut().ok_or("no browser")?;
        b.go_source(source("Samples"));
        open(b, "Drums");
        select(b, "Kick 01.wav");
        p.step_browser();
        p.take_actions();
        Ok(p)
    })();
    let _ = std::fs::remove_dir_all(&dir);
    built
}

