    /// Jay after live test 3: the Warp tempo can be typed. A tap on its
    /// value opens the number pad; Enter sets it (one undo step), a number
    /// out of range keeps the pad open and says why, Cancel changes
    /// nothing, and the wheel steps the number with its push as Enter.
    #[test]
    fn the_warp_tempo_can_be_typed_on_the_number_pad() {
        use crate::app::RowKey;
        use mpfree_sampler_ui::warp_tool::Row;
        use mpfree_sampler_ui::wave_tab::REGION as LIST;
        use mpfree_sampler_ui::widgets::SettingList;
        use mpfree_ui::numpad::{NumPad, KEY_CANCEL, KEY_ENTER, KEY_POINT};
        let mut p = sample_sampler(Fonts::embedded());
        warp_page(&mut p);
        p.on_event(UiEvent {
            widget: LIST.into(),
            kind: EventKind::Step {
                index: Row::Warp.index(),
                delta: 1,
            },
        });
        p.apply(ToUi::SampleLift);
        let bpm = |p: &Player| p.sample.state().unwrap().region.warp.as_ref().unwrap().bpm;
        let before = bpm(&p);
        let tap = |p: &mut Player, (x, y): (i32, i32)| {
            let a = p.touch(4, Touch::Down, x, y);
            p.touch(4, Touch::Up, x, y);
            a
        };
        let open = |p: &mut Player| {
            p.ui.paint(&mut SoftCanvas::new(SCREEN.0, SCREEN.1));
            let list = p.ui.get::<SettingList>(LIST).unwrap();
            assert_eq!(
                list.typed,
                [Row::WarpTempo.index()],
                "warped: it can be typed"
            );
            // The Warp tempo's value on the panel, under its name.
            let value =
                p.ui.targets()
                    .into_iter()
                    .find(|t| t.widget == LIST && t.target.id == "value")
                    .expect("in view")
                    .target;
            tap(p, value.centre());
            assert_eq!(p.page(), NUMPAD_PAGE);
        };
        let key = |p: &mut Player, k: usize| {
            let r = p.ui.rect_of(NUMPAD).unwrap();
            tap(p, NumPad::key_at(r, k))
        };
        open(&mut p);
        assert!(p
            .ui
            .get::<Label>("hint")
            .unwrap()
            .text
            .starts_with("Tap the number"));
        for k in [1, 2, 8, KEY_POINT, 5] {
            key(&mut p, k);
        }
        assert_eq!(key(&mut p, KEY_ENTER), None);
        assert_eq!(p.page(), sample_page::PAGE);
        assert_eq!(bpm(&p), 128.5);
        // One undo step takes it back.
        p.apply(ToUi::SampleUndo(false));
        assert_eq!(bpm(&p), before);
        // Out of range: the pad stays and says the range.
        open(&mut p);
        for k in [1, 5, 0, 0] {
            key(&mut p, k);
        }
        key(&mut p, KEY_ENTER);
        assert_eq!(p.page(), NUMPAD_PAGE);
        assert_eq!(
            p.ui.get::<NumPad>(NUMPAD).unwrap().warning,
            "Warp tempo: type 20 to 999 BPM"
        );
        key(&mut p, KEY_CANCEL);
        assert_eq!((p.page(), bpm(&p)), (sample_page::PAGE, before));
        // The wheel steps from the tempo now (a tenth a detent here) and
        // its push is Enter.
        open(&mut p);
        p.apply(ToUi::SampleWheel(3));
        p.apply(ToUi::Rows(RowKey::Editing(true)));
        assert_eq!(p.page(), sample_page::PAGE);
        assert!((bpm(&p) - (before + 0.3)).abs() < 0.001, "{}", bpm(&p));
    }

    /// Jay, 15 Nov: a short press of the power button opens the power
    /// card over any page; a second press, or Cancel, closes it again.
    #[test]
    fn a_short_press_of_the_power_button_opens_the_power_card() {
        use crate::power::{PowerCard, Step, CARD, PAGE};
        let mut p = sample_player(Fonts::embedded());
        p.apply(ToUi::Show(View::Play));
        p.take_actions();
        p.apply(ToUi::PowerPress);
        assert_eq!(p.page(), PAGE);
        assert!(p.take_actions().contains(&FromUi::Overlay(true)));
        // No library here: nothing is kept, and the card says so.
        let card = p.ui.get::<PowerCard>(CARD).unwrap();
        assert_eq!(card.step, Some(Step::Ask { project: None }));
        // The wheel picks Cancel and the push chooses it.
        p.apply(ToUi::Rows(crate::app::RowKey::Pick(-2)));
        p.apply(ToUi::Rows(crate::app::RowKey::Editing(true)));
        assert_eq!(p.page(), "Play");
        assert!(p.take_actions().contains(&FromUi::Overlay(false)));
        // A second press closes it too, back on the page it was opened over.
        p.apply(ToUi::Show(View::Arrange));
        let arrange = p.page().to_string();
        p.apply(ToUi::PowerPress);
        assert_eq!(p.page(), PAGE);
        p.apply(ToUi::PowerPress);
        assert_eq!(p.page(), arrange);
    }

    /// Shut down hands one word to the system through --power-request's
    /// file, and the card stays up until the app is stopped; without the
    /// option it says it can't and points at the hard power-off.
    #[test]
    fn shut_down_and_restart_go_to_the_systems_file() {
        use crate::power::{Action, PowerCard, Step, CARD, PAGE};
        let dir = std::env::temp_dir().join(format!("mpfree-gui-power-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("power-request");
        let step = |p: &Player| p.ui.get::<PowerCard>(CARD).unwrap().step.clone();
        let tap = |p: &mut Player, label: &str| {
            let r = p.ui.rect_of(CARD).unwrap();
            let card = p.ui.get::<PowerCard>(CARD).unwrap();
            let i = card.buttons().iter().position(|(_, l)| l == label).unwrap();
            let b = card.button_rects(r)[i];
            let a = p.touch(9, Touch::Down, b.x + b.w / 2, b.y + b.h / 2);
            p.touch(9, Touch::Up, b.x + b.w / 2, b.y + b.h / 2);
            a
        };
        // Without --power-request.
        let mut p = sample_player(Fonts::embedded());
        p.apply(ToUi::Show(View::Play));
        p.apply(ToUi::PowerPress);
        tap(&mut p, "Shut down");
        assert!(matches!(step(&p), Some(Step::Unavailable(_))));
        tap(&mut p, "OK");
        assert_eq!(p.page(), "Play");
        // With it: Restart, then Shut down.
        for (label, action, word) in [
            ("Restart", Action::Restart, "restart\n"),
            ("Shut down", Action::ShutDown, "poweroff\n"),
        ] {
            let mut p = sample_player(Fonts::embedded());
            p.set_power_request(file.clone());
            p.apply(ToUi::Show(View::Play));
            p.apply(ToUi::PowerPress);
            tap(&mut p, label);
            assert_eq!(step(&p), Some(Step::Going(action)));
            assert_eq!(std::fs::read_to_string(&file).unwrap(), word);
            // Going: nothing closes it, not even the power button.
            p.apply(ToUi::PowerPress);
            p.apply(ToUi::Show(View::Arrange));
            assert_eq!(p.page(), PAGE);
            assert!(p.ui.get::<PowerCard>(CARD).unwrap().buttons().is_empty());
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Jay after live test 3: a finger held on Play's BPM types the tempo.
    #[test]
    fn a_long_press_on_plays_tempo_types_it() {
        use mpfree_ui::numpad::{NumPad, KEY_ENTER};
        let mut p = sample_player(Fonts::embedded());
        p.apply(ToUi::Show(View::Play));
        p.ui.paint(&mut SoftCanvas::new(SCREEN.0, SCREEN.1));
        let b =
            p.ui.get::<PlayTransport>(play_page::TRANSPORT)
                .unwrap()
                .bpm_area()
                .unwrap();
        let (x, y) = (b.x + b.w / 2, b.y + b.h / 2);
        // A quick tap only taps.
        p.touch(1, Touch::Down, x, y);
        p.tick(0.2);
        p.touch(1, Touch::Up, x, y);
        p.tick(1.0);
        assert_ne!(p.page(), NUMPAD_PAGE);
        // What the tap left goes out, as after every read of the
        // touchscreen (a touch's action waits behind any still waiting).
        let _ = p.take_actions();
        // Held: the number pad, for the tempo.
        assert_eq!(p.touch(2, Touch::Down, x, y), Some(FromUi::TapTempo));
        p.tick(0.4);
        p.tick(0.3);
        assert_eq!(p.page(), NUMPAD_PAGE);
        // The app hands it the wheel and - / + (on Play they pick kits).
        assert!(p.take_actions().contains(&FromUi::Overlay(true)));
        p.touch(2, Touch::Up, x, y);
        let r = p.ui.rect_of(NUMPAD).unwrap();
        let tap = |p: &mut Player, k: usize| {
            let (x, y) = NumPad::key_at(r, k);
            let a = p.touch(3, Touch::Down, x, y);
            p.touch(3, Touch::Up, x, y);
            a
        };
        for k in [9, 5] {
            tap(&mut p, k);
        }
        assert_eq!(
            tap(&mut p, KEY_ENTER),
            Some(FromUi::Time(TimeAction::Transport(
                mpfree_transport::Command::SetTempo(95.0)
            )))
        );
        assert_eq!(p.page(), "Play");
    }

