    /// The kit views in the actions, still boxed (as they go back), and the rest.
    #[allow(clippy::vec_box)]
    fn views(acts: Vec<FromUi>) -> (Vec<Box<ViewSwap>>, Vec<FromUi>) {
        let (mut v, mut rest) = (Vec::new(), Vec::new());
        for a in acts {
            match a {
                FromUi::SampleView(s) => v.push(s),
                a => rest.push(a),
            }
        }
        (v, rest)
    }

    #[test]
    fn a_warped_pad_follows_the_tempo_and_plays_its_stretched_copy_when_ready() {
        use mpfree_sampler_ui::warp_tool::Row;
        use mpfree_sampler_ui::wave_tab::REGION as LIST;
        let pad = mpfree_sampler_ui::sample::PAD;
        let mut p = sample_sampler(Fonts::embedded());
        warp_page(&mut p);
        let warp_row = Row::Warp.index();
        p.on_event(UiEvent {
            widget: LIST.into(),
            kind: EventKind::Step {
                index: warp_row,
                delta: 1,
            },
        });
        let region = p.sample.state().unwrap().region.clone();
        let w = region.warp.clone().expect("warped");
        assert_eq!(w.method, mpfree_sampler::model::WarpMethod::Stretch);
        // The first view repitches (no copy yet) and asks for the copy.
        let (sent, _) = views(p.take_actions());
        let layer = sent[0].view.as_ref().unwrap().layer(pad, 0).unwrap();
        assert_eq!(layer.stretched_frames(), None);
        p.apply(ToUi::SampleViewBack(sent.into_iter().next().unwrap()));
        // The copy comes back from the stretch thread: a new view plays it.
        let t = Instant::now();
        let sent = loop {
            let (sent, _) = views(p.take_actions());
            if !sent.is_empty() {
                break sent;
            }
            assert!(t.elapsed() < Duration::from_secs(30), "no copy");
            std::thread::sleep(Duration::from_millis(5));
        };
        let len = sent[0]
            .view
            .as_ref()
            .unwrap()
            .layer(pad, 0)
            .unwrap()
            .stretched_frames()
            .expect("the copy");
        let want = region.frames() as f64 * f64::from(w.bpm) / 120.0;
        assert!((len as f64 - want).abs() <= 1.0, "{len} vs {want}");
        assert!(
            events_log(&p)
                .iter()
                .any(|l| l.starts_with("sample: stretched")),
            "{:?}",
            events_log(&p)
        );
        p.apply(ToUi::SampleViewBack(sent.into_iter().next().unwrap()));
        // A new tempo: a view at once (repitching), then its own copy.
        let info = TransportInfo {
            bpm: 100.0,
            ..TransportInfo::default()
        };
        p.apply(ToUi::Transport(info));
        assert_eq!(p.sample.tempo(), 100.0);
        let (sent, _) = views(p.take_actions());
        assert_eq!(sent.len(), 1);
        assert_eq!(
            sent[0]
                .view
                .as_ref()
                .unwrap()
                .layer(pad, 0)
                .unwrap()
                .stretched_frames(),
            None
        );
    }

    /// Item 6 of the 14 Nov review: a stretched copy that would leave less
    /// than the memory MPFree keeps free isn't made; the pad repitches,
    /// and that is said once, until the tempo changes.
    #[test]
    fn a_stretched_copy_that_would_leave_too_little_memory_is_not_made_and_the_pad_repitches() {
        use mpfree_sampler_ui::warp_tool::Row;
        use mpfree_sampler_ui::wave_tab::REGION as LIST;
        let pad = mpfree_sampler_ui::sample::PAD;
        let mut p = sample_sampler(Fonts::embedded());
        p.sample.set_mem_free(|| Some(crate::memory::FLOOR));
        warp_page(&mut p);
        let warp_row = Row::Warp.index();
        p.on_event(UiEvent {
            widget: LIST.into(),
            kind: EventKind::Step {
                index: warp_row,
                delta: 1,
            },
        });
        let (sent, _) = views(p.take_actions());
        let layer = sent[0].view.as_ref().unwrap().layer(pad, 0).unwrap();
        assert_eq!(layer.stretched_frames(), None);
        p.apply(ToUi::SampleViewBack(sent.into_iter().next().unwrap()));
        p.tick(0.033);
        let refused = |p: &Player| {
            events_log(p)
                .iter()
                .filter(|l| {
                    l.starts_with(
                        "sample: not stretched, the pad repitches instead (not enough memory: needs about ",
                    )
                })
                .count()
        };
        assert_eq!(refused(&p), 1, "{:?}", events_log(&p));
        let hint = p.ui.get::<Label>("hint").unwrap().text.clone();
        assert!(
            hint.starts_with("Not stretched, the pad repitches instead: not enough memory"),
            "{hint}"
        );
        // No copy comes.
        let t = Instant::now();
        while t.elapsed() < Duration::from_millis(200) {
            let (sent, _) = views(p.take_actions());
            assert!(sent.is_empty());
            std::thread::sleep(Duration::from_millis(5));
            p.tick(0.033);
        }
        // With memory free again, the next tempo's copy is made.
        p.sample.set_mem_free(|| None);
        p.apply(ToUi::Transport(TransportInfo {
            bpm: 100.0,
            ..TransportInfo::default()
        }));
        let t = Instant::now();
        loop {
            let (sent, _) = views(p.take_actions());
            let copy = sent
                .first()
                .and_then(|s| s.view.as_ref()?.layer(pad, 0)?.stretched_frames());
            for s in sent {
                p.apply(ToUi::SampleViewBack(s));
            }
            if copy.is_some() {
                break;
            }
            assert!(t.elapsed() < Duration::from_secs(30), "no copy");
            std::thread::sleep(Duration::from_millis(5));
        }
        assert_eq!(refused(&p), 1);
    }

    /// Item 6 of the 14 Nov review: a sound, or a project's sound, that
    /// would leave less than the memory MPFree keeps free isn't loaded,
    /// and the screen says so in place of the hint.
    #[test]
    fn a_load_or_open_that_would_leave_too_little_memory_is_refused_and_said() {
        use mpfree_sampler::model::Source;
        use mpfree_sampler::wav;
        use std::collections::HashMap;
        let dir = std::env::temp_dir().join(format!("mpfree-sample-short-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let s = Source::new("x", 44_100, 1, vec![0.25; 44_100]).unwrap();
        let path = dir.join("Clap 3.wav");
        std::fs::write(&path, wav::bytes(&s)).unwrap();
        let pad = mpfree_sampler_ui::sample::PAD;
        let mut p = sample_sampler(Fonts::embedded());
        let name = |p: &Player| {
            p.sample
                .project(0)
                .unwrap()
                .pad(pad)
                .map(|pd| pd.name.clone())
        };
        let before = name(&p);
        // Just over the floor free: a second of sound doesn't fit.
        p.sample
            .set_mem_free(|| Some(crate::memory::FLOOR + 100_000));
        p.sample.load_file(path.clone(), false);
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l.starts_with("sample: not loaded (not enough memory: needs about "))
        });
        assert_eq!(name(&p), before);
        let hint = p.ui.get::<Label>("hint").unwrap().text.clone();
        assert!(
            hint.starts_with("Not loaded: not enough memory: needs about "),
            "{hint}"
        );
        // A project's kits: each sound that doesn't fit is left out.
        let (text, sounds) = p.sample.save_part();
        let files: HashMap<String, Vec<u8>> = sounds
            .iter()
            .map(|(f, s)| (f.clone(), wav::bytes(s)))
            .collect();
        p.sample.open_part(
            text,
            Box::new(move |f| files.get(f).cloned().ok_or_else(|| "missing".to_string())),
        );
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l.ends_with(" opened") && !l.contains("weren't"))
        });
        let log = events_log(&p);
        assert!(
            log.iter()
                .any(|l| l.contains(" left out (not enough memory: needs about ")),
            "{log:?}"
        );
        let hint = p.ui.get::<Label>("hint").unwrap().text.clone();
        assert!(
            hint.ends_with(
                " of the project's sounds left out: not enough memory; the Console lists them"
            ),
            "{hint}"
        );
        // With room, the sound loads.
        p.sample.set_mem_free(|| None);
        p.sample.load_file(path, false);
        tick_until(&mut p, |p| name(p).as_deref() == Some("Clap 3"));
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn the_warp_tool_pins_the_hits_and_the_copy_goes_through_them() {
        use mpfree_sampler_ui::warp_tool::Row;
        use mpfree_sampler_ui::wave_tab::{Tool, REGION as LIST, TOOLS};
        use mpfree_sampler_ui::widgets::ToolStrip;
        let pad = mpfree_sampler_ui::sample::PAD;
        let mut p = sample_sampler(Fonts::embedded());
        // The tools strip's Warp, after Trim and Slice.
        let r = p.ui.rect_of(TOOLS).unwrap();
        let i = Tool::ALL.iter().position(|t| *t == Tool::Warp).unwrap();
        let t = p.ui.get::<ToolStrip>(TOOLS).unwrap().tool_rect(r, i);
        assert_eq!(p.touch(9, Touch::Down, t.x + 5, t.y + 5), None);
        p.touch(9, Touch::Up, t.x + 5, t.y + 5);
        assert_eq!(
            (p.page(), p.sample.editor(), p.sample.tool()),
            (sample_page::PAGE, sample_page::Editor::Wave, Tool::Warp)
        );
        assert!(p
            .ui
            .get::<Label>("hint")
            .unwrap()
            .text
            .contains("Tap a hit: pin it to the grid"));
        // Warp on (Stretch), then Pin hits.
        p.on_event(UiEvent {
            widget: LIST.into(),
            kind: EventKind::Step {
                index: Row::Warp.index(),
                delta: 1,
            },
        });
        let (sent, _) = views(p.take_actions());
        p.apply(ToUi::SampleViewBack(sent.into_iter().next().unwrap()));
        p.apply(ToUi::SampleLift);
        p.on_event(UiEvent {
            widget: LIST.into(),
            kind: EventKind::Tab(Row::PinHits.index()),
        });
        let w = p.sample.state().unwrap().region.warp.clone().unwrap();
        assert!(w.pins.len() >= 4, "{:?}", w.pins);
        // The wheel navigation (app::RowKey, live test 2): the wheel picks
        // the list's rows, its push opens one, and the wheel or - / + then
        // step it, as a tap on its arrow; SHIFT + - / + still zoom.
        {
            use crate::app::RowKey;
            use mpfree_sampler_ui::widgets::SettingList;
            let list = |p: &Player| {
                let l = p.ui.get::<SettingList>(LIST).unwrap();
                (
                    l.selected,
                    l.editing,
                    l.rows[Row::Grid.index()].value.clone(),
                )
            };
            assert_eq!(list(&p).0, Row::Warp.index());
            p.apply(ToUi::Rows(RowKey::Pick(Row::Grid.index() as i32)));
            assert_eq!(list(&p).0, Row::Grid.index());
            p.apply(ToUi::Rows(RowKey::Pick(-1)));
            p.apply(ToUi::Rows(RowKey::Pick(1)));
            let (at, editing, grid) = list(&p);
            assert_eq!((at, editing), (Row::Grid.index(), false));
            p.apply(ToUi::Rows(RowKey::Editing(true)));
            assert!(list(&p).1);
            p.apply(ToUi::Rows(RowKey::Step(1)));
            assert_ne!(list(&p).2, grid, "the wheel stepped Grid");
            p.apply(ToUi::Rows(RowKey::Step(-1)));
            assert_eq!(list(&p).2, grid, "and back");
            p.apply(ToUi::Rows(RowKey::Editing(false)));
            assert!(!list(&p).1);
            p.apply(ToUi::SampleWheel(1));
            p.apply(ToUi::Rows(RowKey::Pick(-99)));
            assert_eq!(list(&p).0, 0);
        }
        // The copy made through the pins comes back and is played.
        let t = Instant::now();
        let sent = loop {
            let (sent, _) = views(p.take_actions());
            if sent.iter().any(|s| {
                s.view
                    .as_ref()
                    .and_then(|v| v.layer(pad, 0))
                    .is_some_and(|l| l.stretched_frames().is_some())
            }) {
                break sent;
            }
            for s in sent {
                p.apply(ToUi::SampleViewBack(s));
            }
            assert!(t.elapsed() < Duration::from_secs(30), "no copy");
            std::thread::sleep(Duration::from_millis(5));
        };
        for s in sent {
            p.apply(ToUi::SampleViewBack(s));
        }
        // UNDO takes the pins off again.
        p.apply(ToUi::SampleLift);
        p.apply(ToUi::SampleUndo(false));
        let w = p.sample.state().unwrap().region.warp.clone().unwrap();
        assert!(w.pins.is_empty());
        assert_eq!(p.page(), sample_page::PAGE);
    }

    fn events_log(p: &Player) -> Vec<String> {
        p.ui.get::<LogPanel>("events")
            .unwrap()
            .lines()
            .map(|(l, _)| l.clone())
            .collect()
    }

    /// Ticks until `done` (the sample page's threads finish), for at most
    /// [`WORKER_WAIT`].
    fn tick_until(p: &mut Player, mut done: impl FnMut(&mut Player) -> bool) {
        let end = Instant::now() + WORKER_WAIT;
        while !done(p) {
            assert!(Instant::now() < end, "{:?}", events_log(p));
            std::thread::sleep(Duration::from_millis(5));
            p.tick(0.033);
        }
    }

    #[test]
    fn a_project_keeps_its_sounds_analysis_and_opens_without_analysing_them() {
        use mpfree_sampler::wav;
        use std::collections::HashMap;
        let pad = mpfree_sampler_ui::sample::PAD;
        let p = sample_sampler(Fonts::embedded());
        let (text, sounds) = p.sample.save_part();
        // The sound shown has its analysis worked out: it is kept beside
        // it, named by the sound and the analysis's version.
        let caches = p.sample.cache_part();
        assert_eq!(caches.len(), 1);
        let (file, view) = &caches[0];
        assert_eq!(*file, format!("{}.a1.peaks", sounds[0].1.id()));
        assert!(view.ready);
        let mut files: HashMap<String, Vec<u8>> = sounds
            .iter()
            .map(|(f, s)| (f.clone(), wav::bytes(s)))
            .collect();
        files.insert(file.clone(), view.to_cache().unwrap());
        // Another session opens the project: the sound shows its hits,
        // tempo and note as soon as the kit is there, with nothing left
        // for the worker.
        let mut q = sample_player(Fonts::embedded());
        q.apply(ToUi::SampleKits {
            projects: vec![Project::new()],
            rate: mpfree_sampler_ui::sample::RATE,
        });
        q.apply(ToUi::Kit(0));
        q.apply(ToUi::Show(View::Sample));
        let _ = q.take_actions();
        q.sample.open_part(
            text,
            Box::new(move |f| files.get(f).cloned().ok_or_else(|| "missing".to_string())),
        );
        tick_until(&mut q, |q| q.sample.project(0).unwrap().pad(pad).is_some());
        assert!(!q.sample.analysing(), "nothing analysed again");
        let log = events_log(&q);
        assert!(
            log.iter()
                .any(|l| l == "sample: the analysis of 1 sound read from the project"),
            "{log:?}"
        );
        // And its file is kept again with the next save (the library
        // leaves it as it is).
        assert_eq!(q.sample.cache_part().len(), 1);
    }

    #[test]
    fn the_kits_save_with_their_sounds_and_open_again() {
        use mpfree_sampler::{save, wav};
        use std::collections::HashMap;
        let pad = mpfree_sampler_ui::sample::PAD;
        let p = sample_sampler(Fonts::embedded());
        let (text, sounds) = p.sample.save_part();
        assert!(text.starts_with(save::FORMAT));
        let saved = p.sample.project(0).unwrap().clone();
        assert_eq!(sounds.len(), saved.sources().len());
        // What the library would keep in the project's samples/.
        let files: HashMap<String, Vec<u8>> = sounds
            .iter()
            .map(|(f, s)| (f.clone(), wav::bytes(s)))
            .collect();
        // Another session: the same kit slots, nothing on them.
        let mut q = sample_player(Fonts::embedded());
        q.apply(ToUi::SampleKits {
            projects: vec![Project::new()],
            rate: mpfree_sampler_ui::sample::RATE,
        });
        q.apply(ToUi::Kit(0));
        assert!(q.sample.project(0).unwrap().pad(pad).is_none());
        let _ = q.take_actions();
        q.sample.open_part(
            text,
            Box::new(move |f| files.get(f).cloned().ok_or_else(|| "missing".to_string())),
        );
        tick_until(&mut q, |q| q.sample.project(0).unwrap().pad(pad).is_some());
        let got = q.sample.project(0).unwrap();
        assert_eq!(got.pad(pad), saved.pad(pad));
        assert_eq!(got.chop_sets, saved.chop_sets);
        assert!(!got.can_undo(), "UNDO doesn't take the opened kit apart");
        let log = events_log(&q);
        assert!(log.iter().any(|l| l == "sample: 1 kit opened"), "{log:?}");
        // The Play page's names follow, and the audio thread gets the kit.
        assert_eq!(q.kits[0].pads[pad].as_deref(), Some("Break 92"));
        assert!(q.sample.take_view().is_some());
        // A part that isn't one says so and leaves the kits alone.
        q.sample
            .open_part("hello".into(), Box::new(|_| Err("no".to_string())));
        tick_until(&mut q, |q| {
            events_log(q)
                .iter()
                .any(|l| l.starts_with("sample: the project's kits weren't opened"))
        });
        assert!(q.sample.project(0).unwrap().pad(pad).is_some());
    }

    /// BROWSE's Plugins place through the browser and the worker, on a
    /// scratch data folder: its own hint line, a zip on the stick that is
    /// not a plugin flagged, and Delete zip asked twice.
    #[test]
    fn the_plugins_place_lists_the_stick_and_deletes_a_zip_on_the_second_tap() {
        use mpfree_browser_ui::sample::source;
        use mpfree_browser_ui::{Input, PluginButton, PluginInput, PluginsView};
        let dir = std::env::temp_dir().join(format!("mpfree-plugins-place-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let plugins = dir.join("files").join(crate::plugins::PLUGINS_FOLDER);
        std::fs::create_dir_all(&plugins).unwrap();
        std::fs::write(plugins.join("notes.zip"), b"not a zip").unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        p.set_browser(mpfree_browser_ui::Browser::inline(lib), "");
        p.plugin_page = crate::plugin_page::PluginPage::without_fetching();
        p.take_actions();
        p.apply(ToUi::Show(View::Browser));
        p.browser.as_mut().unwrap().go_source(source("Plugins"));
        p.step_browser();
        assert_eq!(
            p.ui.get::<Label>("hint").unwrap().text,
            mpfree_browser_ui::PLUGINS_HINT
        );
        let send = |p: &mut Player, i: PluginInput| {
            p.browser.as_mut().unwrap().input(Input::Plugins(i));
            p.step_browser();
        };
        let shown = |p: &Player| p.browser.as_ref().unwrap().screen().plugins.unwrap();
        send(&mut p, PluginInput::View(PluginsView::OnStick));
        tick_until(&mut p, |p| !shown(p).rows.is_empty());
        let s = shown(&p);
        assert_eq!(s.rows[0].name, "notes.zip");
        assert_eq!(s.rows[0].tag, "Can't install");
        assert!(s.detail.note.contains("not a zip"), "{}", s.detail.note);
        assert!(!s.detail.buttons.contains(&PluginButton::InstallZip));
        send(&mut p, PluginInput::Button(PluginButton::DeleteZip));
        assert!(shown(&p)
            .detail
            .buttons
            .contains(&PluginButton::ConfirmDeleteZip));
        assert!(plugins.join("notes.zip").exists(), "not on the first tap");
        send(&mut p, PluginInput::Button(PluginButton::ConfirmDeleteZip));
        tick_until(&mut p, |p| shown(p).rows.is_empty());
        assert!(!plugins.join("notes.zip").exists());
        assert_eq!(shown(&p).status, "Deleted notes.zip");
        // Another place: the browser's own hint line again.
        p.browser.as_mut().unwrap().go_source(source("Samples"));
        p.step_browser();
        assert_eq!(
            p.ui.get::<Label>("hint").unwrap().text,
            mpfree_browser_ui::BROWSER_HINT
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Save kit writes the kit the pads play as a kit folder (kit.txt and
    /// its sounds, named for them); loading that folder puts the kit back,
    /// pads and names, in place of the kit the pads play.
    #[test]
    fn a_kit_saves_as_a_folder_and_loads_back() {
        use mpfree_browser_ui::BrowseAction as A;
        use mpfree_library::{Loc, Place};
        let dir = std::env::temp_dir().join(format!("mpfree-kit-file-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        let pads = |p: &Player, k: usize| -> Vec<Option<String>> {
            (0..16)
                .map(|i| {
                    p.sample
                        .project(k)
                        .and_then(|pr| pr.pad(i))
                        .filter(|pd| !pd.layers.is_empty())
                        .map(|pd| pd.name.clone())
                })
                .collect()
        };
        let before = pads(&p, 0);
        assert!(before.iter().any(Option::is_some));
        // Save kit (from the top of Kits, where the browser sends it).
        p.browse_action(A::SaveKitRequested);
        let kits = lib.list(&Loc::top(Place::Kits)).unwrap();
        assert_eq!(kits.len(), 1, "{kits:?}");
        assert_eq!(kits[0].kind, mpfree_library::Kind::Kit);
        assert_eq!(kits[0].name, "Breaks");
        let kit = Loc::new(Place::Kits, &["Breaks"]).unwrap();
        let text = lib.kit_text(&kit).unwrap();
        assert!(text.starts_with("mpfree-sampler 1\nkits = 1\n"), "{text}");
        let inside = lib.list(&kit).unwrap();
        assert!(inside.iter().filter(|e| e.name.ends_with(".wav")).count() >= 1);
        assert!(inside
            .iter()
            .all(|e| e.name == "kit.txt" || e.name.ends_with(".wav")));
        // A kit made by hand, one pad playing one sound: loading it puts it
        // in place of the kit the pads play, named for its folder.
        let solo =
            mpfree_sampler::model::Source::new("Solo", 44_100, 1, vec![0.25; 4_410]).unwrap();
        let bytes = mpfree_sampler::wav::bytes(&solo);
        lib.save_kit(
            &Loc::top(Place::Kits),
            "One pad",
            "mpfree-sampler 1\nkits = 1\nkit.0.name = One pad\nkit.0.sources = 1\n\
             kit.0.source.0.file = Solo.wav\nkit.0.pad.0.name = Solo\nkit.0.pad.0.layers = 1\n\
             kit.0.pad.0.layer.0.source = 0\nkit.0.pad.0.layer.0.region.end = 4410\n",
            &[mpfree_library::NewSample::new(
                "Solo.wav",
                std::sync::Arc::new(move |w: &mut dyn io::Write| w.write_all(&bytes)),
            )],
        )
        .unwrap();
        let one = Loc::new(Place::Kits, &["One pad"]).unwrap();
        p.browse_action(A::LoadKit {
            loc: one.clone(),
            path: lib.kit_path(&one).unwrap(),
        });
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l == "sample: kit 1 is now One pad")
        });
        let mut want = vec![None; 16];
        want[0] = Some("Solo".to_string());
        assert_eq!(pads(&p, 0), want);
        // And the saved kit back: pad for pad as it was.
        p.browse_action(A::LoadKit {
            loc: kit.clone(),
            path: lib.kit_path(&kit).unwrap(),
        });
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l == "sample: kit 1 is now Breaks")
        });
        assert_eq!(pads(&p, 0), before);
        // Loading changed the work.
        assert!(p.sample.edits > 0);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// New track with this kit (the browser): a track is added as + Kit
    /// track adds one, and once it is armed the kit folder loads into the
    /// empty kit it gets, leaving the kit on the pads as it was.
    #[test]
    fn new_track_with_this_kit_adds_a_track_that_plays_the_kit() {
        use mpfree_browser_ui::BrowseAction as A;
        use mpfree_library::{Loc, Place};
        let dir = std::env::temp_dir().join(format!("mpfree-kit-track-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        // An empty user kit after the kits, with a sampler kit for each.
        let mut kits = p.kits.clone();
        let n = kits
            .iter()
            .position(|k| k.synth.is_some())
            .unwrap_or(kits.len());
        kits.insert(
            n,
            KitView {
                name: format!("Kit {}", n + 1),
                pads: vec![None; 128],
                colour: [0x10, 0x10, 0x10],
                chip: None,
                synth: None,
                pitches: Vec::new(),
                user: true,
                key: None,
                tags: Vec::new(),
            },
        );
        p.apply(ToUi::Kits(kits));
        let (first, _) = mpfree_sampler_ui::sample::project();
        let mut projects = vec![first];
        projects.resize_with(n + 1, mpfree_sampler::model::Project::new);
        p.apply(ToUi::SampleKits {
            projects,
            rate: mpfree_sampler_ui::sample::RATE,
        });
        sample_pattern(&mut p, 0);
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        let pads = |p: &Player, k: usize| -> Vec<Option<String>> {
            (0..16)
                .map(|i| {
                    p.sample
                        .project(k)
                        .and_then(|pr| pr.pad(i))
                        .filter(|pd| !pd.layers.is_empty())
                        .map(|pd| pd.name.clone())
                })
                .collect()
        };
        let on_the_pads = pads(&p, 0);
        assert!(on_the_pads.iter().any(Option::is_some));
        assert!(pads(&p, n).iter().all(Option::is_none));
        // A kit's Load names the armed track, whose kit it replaces.
        let kit_on = |p: &mut Player| {
            p.step_browser();
            p.browser.as_ref().unwrap().screen().kit_on
        };
        let armed = p.time.armed.expect("a track is armed");
        let name = p.time.tracks[armed].name.clone();
        assert_eq!(kit_on(&mut p), Some(name));
        p.browse_action(A::SaveKitRequested);
        let kit = Loc::new(Place::Kits, &["Breaks"]).unwrap();
        let ask = A::NewTrackWithKit {
            loc: kit.clone(),
            path: lib.kit_path(&kit).unwrap(),
        };
        let before = p.time.tracks.len();
        p.browse_action(ask.clone());
        assert_eq!(p.take_actions(), vec![FromUi::Time(TimeAction::AddTrack)]);
        assert!(events_log(&p)
            .iter()
            .any(|l| l == "browser: a new track for the kit Breaks"));
        // One at a time.
        p.browse_action(ask);
        assert!(p.take_actions().is_empty());
        // The time engine adds it, armed: it gets the empty kit, and the
        // kit folder goes into that kit.
        let mut st = p.time.clone();
        let mut added = st.tracks[0].clone();
        added.name = format!("Track {}", before + 1);
        added.slots.iter_mut().for_each(|s| *s = None);
        st.tracks.push(added);
        st.armed = Some(before);
        p.apply(ToUi::Time(Box::new(st)));
        assert_eq!(p.take_actions(), vec![FromUi::Kit(n)]);
        let now = format!("sample: kit {} is now Breaks", n + 1);
        tick_until(&mut p, |p| events_log(p).contains(&now));
        assert_eq!(pads(&p, n), on_the_pads);
        assert_eq!(pads(&p, 0), on_the_pads, "the pads' kit is as it was");
        assert_eq!(kit_on(&mut p), Some(format!("Track {}", before + 1)));
        // With no room for another track, it says so and adds nothing.
        let mut full = p.time.clone();
        let more = full.tracks[0].clone();
        full.tracks.resize(mpfree_seq::MAX_TRACKS, more);
        p.apply(ToUi::Time(Box::new(full)));
        p.take_actions();
        p.browse_action(A::NewTrackWithKit {
            loc: kit.clone(),
            path: lib.kit_path(&kit).unwrap(),
        });
        assert!(p.take_actions().is_empty());
        assert!(
            p.told
                .as_ref()
                .is_some_and(|(t, _)| t.contains("no room for a new one")),
            "{:?}",
            p.told
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The preset picker's New track (step 4c): + Track
    /// adds one, and once it is armed (and a file of the musician's is
    /// read) the sound loop is asked to give it a synth playing the preset.
    #[test]
    fn new_track_with_this_sound_adds_a_track_and_asks_for_its_synth() {
        use crate::presets::Give;
        use mpfree_browser_ui::{BrowseAction as A, PresetFrom};
        let mut p = sample_sampler(Fonts::embedded());
        sample_pattern(&mut p, 0);
        p.take_actions();
        // The time engine adds a track: armed (the new one) or not.
        let add = |p: &mut Player, armed_new: bool| {
            let mut st = p.time.clone();
            let n = st.tracks.len();
            let mut added = st.tracks[0].clone();
            added.name = format!("Track {}", n + 1);
            added.slots.iter_mut().for_each(|s| *s = None);
            st.tracks.push(added);
            st.armed = Some(if armed_new { n } else { 0 });
            p.apply(ToUi::Time(Box::new(st)));
            n
        };
        let told = |p: &Player, what: &str| p.told.as_ref().is_some_and(|(t, _)| t.contains(what));
        let ask = |engine: &str, name: &str, from| A::NewTrackWithPreset {
            engine: engine.into(),
            name: name.into(),
            from,
        };

        // One of the engine's own.
        p.browse_action(ask("FM", "Glass", PresetFrom::Factory(1)));
        assert_eq!(p.take_actions(), vec![FromUi::Time(TimeAction::AddTrack)]);
        assert!(events_log(&p)
            .iter()
            .any(|l| l == "browser: a new track for FM's Glass"));
        // One new track at a time.
        p.browse_action(ask("FM", "Glass", PresetFrom::Factory(1)));
        assert!(p.take_actions().is_empty());
        assert!(told(&p, "still on its way"));
        let track = add(&mut p, true);
        p.poll_sound_track();
        assert_eq!(
            p.take_actions(),
            vec![FromUi::NewTrackSound {
                track,
                engine: "FM".into(),
                give: Give::Factory(1),
            }]
        );
        assert!(p.sound_track.is_none());

        // One of the musician's: its file is read first.
        let dir = std::env::temp_dir().join(format!("mpfree-sound-track-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("Metal bass.preset");
        std::fs::write(&file, "the preset's text").unwrap();
        p.browse_action(ask("FM", "Metal bass", PresetFrom::File(file)));
        assert_eq!(p.take_actions(), vec![FromUi::Time(TimeAction::AddTrack)]);
        let track = add(&mut p, true);
        let end = Instant::now() + WORKER_WAIT;
        let asked = loop {
            p.poll_sound_track();
            let asked = p.take_actions();
            if !asked.is_empty() {
                break asked;
            }
            assert!(Instant::now() < end, "the file was never read");
            std::thread::sleep(Duration::from_millis(5));
        };
        assert_eq!(
            asked,
            vec![FromUi::NewTrackSound {
                track,
                engine: "FM".into(),
                give: Give::Text {
                    name: "Metal bass".into(),
                    text: "the preset's text".into(),
                },
            }]
        );
        // A file that isn't there: said, and the new track keeps its kit.
        p.browse_action(ask("FM", "Gone", PresetFrom::File(dir.join("Gone.preset"))));
        p.take_actions();
        add(&mut p, true);
        let end = Instant::now() + WORKER_WAIT;
        while p.sound_track.is_some() {
            assert!(Instant::now() < end, "the file was never tried");
            std::thread::sleep(Duration::from_millis(5));
            p.poll_sound_track();
        }
        assert!(p.take_actions().is_empty());
        assert!(told(&p, "Gone wasn't read"));

        // Another track armed before the new one: given up, said.
        p.browse_action(ask("FM", "Glass", PresetFrom::Factory(1)));
        p.take_actions();
        add(&mut p, false);
        p.poll_sound_track();
        assert!(p.take_actions().is_empty());
        assert!(p.sound_track.is_none());
        assert!(told(
            &p,
            "Glass wasn't put on a new track: another track was armed first"
        ));

        // With no room for another track, it says so and adds nothing.
        let mut full = p.time.clone();
        let more = full.tracks[0].clone();
        full.tracks.resize(mpfree_seq::MAX_TRACKS, more);
        p.apply(ToUi::Time(Box::new(full)));
        p.take_actions();
        p.browse_action(ask("FM", "Glass", PresetFrom::Factory(1)));
        assert!(p.take_actions().is_empty());
        assert!(told(&p, "no room for a new one"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// BROWSE, SHIFT + BROWSE, Open and New project through the screen, on
    /// a library in a scratch folder.
    #[test]
    fn a_project_saves_opens_again_and_new_starts_empty() {
        use crate::project::{self, Collected, Defaults};
        use mpfree_browser_ui::sample::{select, source};
        use mpfree_browser_ui::{Button, Input};
        use mpfree_fx::ids::mixer as mx;
        use mpfree_fx::StripId;
        use mpfree_midi::setup::{PortInput, TempoSource, DIN_NAME};
        let dir = std::env::temp_dir().join(format!("mpfree-project-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        // The I/O setup: its song settings go in the project (Tempo from a
        // port, here), the rig's (a port's input) stay with the MPC.
        let io: mpfree_midi_ui::Shared =
            std::sync::Arc::new(std::sync::Mutex::new(mpfree_midi_ui::sample::rig()));
        p.apply(ToUi::IoModel(io.clone()));
        let keystep = || io.lock().unwrap().setup.port("Keystep 37").input;
        let tempo_from = || io.lock().unwrap().setup.tempo.clone();
        assert_eq!(keystep(), PortInput::LearnOnly);
        // BROWSE: the whole browser over the page.
        p.apply(ToUi::Show(View::Browser));
        assert_eq!(p.page(), mpfree_browser_ui::BROWSER_PAGE);
        // SHIFT + BROWSE: the loop's parts come, the screen adds its own and
        // the lot is saved, named for the time.
        let mut mix = crate::mixing::MixHost::new(44_100, -6.0, 0.0);
        mix.mixer.set_now(StripId::Track(2), mx::VOLUME, -3.0);
        for _ in 0..50 {
            mix.run_silent_period();
        }
        let mut clips = crate::time::TimeHost::new(44_100, 98.0)
            .unwrap()
            .project()
            .clone();
        let mut clip = mpfree_seq::Clip::new("Groove", 1920);
        clip.add_note(mpfree_seq::Note::new(0, 240, 36, 100))
            .unwrap();
        clips.tracks[0].slots[0] = Some(clip);
        // Its lasting id, as a project in the app has it (Arrange 1.1).
        clips.give_clip_ids();
        let synth = crate::synth::Synth::new(44_100);
        // Loop 2 with one layer, as the looper's save gives it.
        let layer: Vec<f32> = (0..2 * 4410).map(|k| (k % 97) as f32 / 200.0).collect();
        let loops = mpfree_looper::save::Saved {
            rate: 44_100,
            selected: 1,
            loops: vec![(
                1,
                mpfree_looper::save::LoopFile {
                    frames: 4410,
                    ticks: 96,
                    origin: 0,
                    level: 0.8,
                    muted: false,
                    bars: Some(1),
                    after: mpfree_looper::After::Play,
                    starts: mpfree_looper::Starts::Bar,
                    fade_old: 1.0,
                    speed: 0,
                    rate: 0,
                    layers: vec![mpfree_looper::save::LayerFile {
                        level: 0.5,
                        pan: -0.25,
                        muted: false,
                        solo: false,
                        faded: 1.0,
                        file: String::new(),
                        audio: layer.clone(),
                    }],
                },
            )],
        };
        // Audio 2 with a region of a mono take, as the tracks' save gives it.
        let take: Vec<f32> = (0..4410).map(|k| (k % 89) as f32 / 300.0).collect();
        let audio = mpfree_audiotracks::save::Saved {
            rate: 44_100,
            tracks: vec![mpfree_audiotracks::save::TrackFile {
                index: 1,
                input: mpfree_audiotracks::Input::Right,
                monitor: mpfree_audiotracks::Monitor::Auto,
                level: 0.5,
                pan: 0.0,
                muted: false,
                solo: true,
                from: String::new(),
                regions: vec![mpfree_audiotracks::Region {
                    start: 0,
                    end: 960,
                    take: 4,
                    src: 0,
                    gain: 1.0,
                    fade_in: 0,
                    fade_out: 0,
                }],
            }],
            takes: vec![mpfree_audiotracks::save::TakeFile {
                id: 4,
                track: 1,
                group: 1,
                pass: 0,
                bpm: 98.0,
                anchor: 0.0,
                frames: 4410,
                channels: 1,
                file: String::new(),
                audio: take.clone(),
            }],
        };
        let c = Collected {
            tempo: 98.0,
            swing: mpfree_transport::time::Swing::new(240, 62).unwrap(),
            clips: clips.clone(),
            mixer: project::mixer_text(&mix.mixer, 0),
            modu: String::new(),
            synth: project::synth_text(&Default::default(), &synth.sounds()),
            arp: "mpfree-arp 1\ntrack 1\nmode = arp\n".to_string(),
            instruments: String::new(),
            track_kits: String::new(),
            instrument_list: crate::instrument_list::InstrumentList::new().text(),
            pads: String::new(),
            perform: String::new(),
            loops: Some(loops),
            audio: Some(audio),
        };
        p.apply(ToUi::ProjectParts(Box::new(c)));
        p.step_browser();
        let loc = p
            .browser
            .as_ref()
            .unwrap()
            .project()
            .cloned()
            .expect("saved");
        let snap = lib.open_project(&loc).unwrap();
        for part in [
            project::CLIPS,
            project::MIXER,
            project::MOD,
            project::SYNTH,
            project::SAMPLER,
            project::LOOPER,
            project::ARP,
            project::MIDI,
            project::AUDIOTRACKS,
        ] {
            assert!(snap.part(part).is_some(), "{part}");
        }
        assert_eq!(snap.meta.tempo, 98.0);
        assert!(events_log(&p)
            .iter()
            .any(|l| *l == format!("project: saved {}", loc.name())));
        // Open it from the Projects list: the engines come built, for the
        // loop to swap in, and the I/O setup's song settings come back.
        io.lock().unwrap().setup.tempo = TempoSource::Internal;
        let b = p.browser.as_mut().unwrap();
        b.go_source(source("Projects"));
        select(b, loc.name());
        b.push();
        p.step_browser();
        let opened = p
            .take_actions()
            .into_iter()
            .find_map(|a| match a {
                FromUi::OpenProject(o) => Some(o),
                _ => None,
            })
            .expect("opened");
        assert_eq!(tempo_from(), TempoSource::Port(DIN_NAME.into()));
        assert_eq!(opened.tempo, Some(98.0));
        assert_eq!(opened.swing, mpfree_transport::time::Swing::new(240, 62));
        assert!(opened.notes.is_empty(), "{:?}", opened.notes);
        assert_eq!(opened.time.as_ref().unwrap().project(), &clips);
        let mixed = opened.mix.as_ref().unwrap();
        let t2 = mixed
            .strips
            .iter()
            .find(|(s, _)| *s == StripId::Track(2))
            .unwrap();
        assert!(t2.1.contains(&(mx::VOLUME, -3.0)));
        assert_eq!(opened.synth.as_ref().unwrap().1, synth.sounds());
        assert!(opened.clear_loops);
        assert!(opened.clear_audio);
        assert_eq!(
            opened.arp.as_deref(),
            Some("mpfree-arp 1\ntrack 1\nmode = arp\n")
        );
        p.apply(ToUi::ProjectBack(opened));
        // The loops and the audio tracks follow, each read on its own
        // thread, with their audio.
        let end = Instant::now() + Duration::from_secs(5);
        let (mut loops, mut audio) = (None, None);
        while loops.is_none() || audio.is_none() {
            p.tick(0.033);
            for a in p.take_actions() {
                match a {
                    FromUi::OpenLoops(l) => loops = Some(l),
                    FromUi::OpenAudio(a) => audio = Some(a),
                    _ => {}
                }
            }
            assert!(Instant::now() < end, "{:?}", events_log(&p));
            std::thread::sleep(Duration::from_millis(5));
        }
        let (loops, audio) = (loops.unwrap(), audio.unwrap());
        assert_eq!((loops.selected, loops.loops.len()), (1, 1));
        let (n, f) = &loops.loops[0];
        assert_eq!((*n, f.frames, f.level), (1, 4410, 0.8));
        assert_eq!(f.layers[0].pan, -0.25);
        assert_eq!(f.layers[0].audio, layer);
        assert!(f.layers[0].file.starts_with("loop-"));
        // The audio tracks, with their take's audio from its WAV.
        assert_eq!(audio.tracks.len(), 1);
        let t = &audio.tracks[0];
        assert_eq!(
            (t.index, t.input, t.level, t.solo),
            (1, mpfree_audiotracks::Input::Right, 0.5, true)
        );
        assert_eq!(t.regions[0].take, 4);
        let k = &audio.takes[0];
        assert_eq!((k.id, k.frames, k.channels), (4, 4410, 1));
        assert_eq!(k.audio, take);
        assert!(
            k.file.starts_with("take-") && k.file.ends_with(".wav"),
            "{}",
            k.file
        );
        assert!(lib.sample_path(&loc, &k.file).is_ok());
        assert!(!p.browser.as_ref().unwrap().unsaved());
        // Once the open settles, a pad played isn't an edit; a new clip is.
        p.opened_at = None;
        p.saw_action(&FromUi::PreviewStop);
        p.saw_action(&FromUi::Time(TimeAction::Transport(
            mpfree_transport::Command::Play,
        )));
        // Nor the UNDO light, the undo list or a list over the page, nor
        // a kit's view still on its way after the settle time (the open's,
        // on a slow machine: the Sample page made no edit).
        let view = || {
            FromUi::SampleView(Box::new(ViewSwap {
                kit: 0,
                view: None,
                routes: Vec::new(),
            }))
        };
        p.saw_action(&FromUi::UndoReady(true));
        p.saw_action(&FromUi::UndoHistory(UndoOn::Mixer));
        p.saw_action(&FromUi::Overlay(true));
        p.saw_action(&view());
        assert!(!p.browser.as_ref().unwrap().unsaved());
        // A view after a Sample page edit is one.
        p.sample.edits += 1;
        p.saw_action(&view());
        assert!(p.browser.as_ref().unwrap().unsaved());
        p.browser.as_mut().unwrap().set_unsaved(false);
        p.saw_action(&view());
        assert!(!p.browser.as_ref().unwrap().unsaved());
        p.saw_action(&FromUi::Time(TimeAction::NewClip { track: 0, slot: 1 }));
        assert!(p.browser.as_ref().unwrap().unsaved());
        // A Synth tab option or the arp changed with the controls.
        p.browser.as_mut().unwrap().set_unsaved(false);
        p.apply(ToUi::Edited);
        assert!(p.browser.as_ref().unwrap().unsaved());
        // New project before the sound has started says so.
        let new = |p: &mut Player| {
            let b = p.browser.as_mut().unwrap();
            b.go_source(source("Projects"));
            b.input(Input::Button(Button::NewProject));
            // Over unsaved work it asks first; the push says yes.
            b.push();
            p.step_browser();
            // As on a slow machine: the kits took longer than the settle
            // time. What New sent is still its own, not an edit.
            p.opened_at = p.opened_at.and_then(|t| t.checked_sub(OPEN_SETTLE * 2));
            p.take_actions().into_iter().find_map(|a| match a {
                FromUi::OpenProject(o) => Some(o),
                _ => None,
            })
        };
        assert!(new(&mut p).is_none());
        assert!(events_log(&p)
            .iter()
            .any(|l| l.starts_with("project: not ready for a new project")));
        // With the start's parts: an empty song of 8 tracks, the factory
        // kits, and no project (Save names a new one).
        let defaults = || {
            Box::new(Defaults {
                tempo: 120.0,
                mixer: project::mixer_text(
                    &crate::mixing::MixHost::new(44_100, -6.0, 0.0).mixer,
                    0,
                ),
                modu: String::new(),
                synth: project::synth_text(&Default::default(), &synth.sounds()),
            })
        };
        p.apply(ToUi::ProjectDefaults(defaults()));
        p.browser.as_mut().unwrap().set_unsaved(true);
        let fresh = new(&mut p).expect("a new project");
        assert_eq!(fresh.what, "a new project");
        assert!(fresh.clear_loops);
        assert!(fresh.clear_audio);
        assert_eq!(fresh.tempo, Some(120.0));
        assert_eq!(fresh.swing, Some(Default::default()));
        assert_eq!(fresh.arp, None, "every arp at its default");
        // The I/O setup's song settings at their defaults; the rig's kept.
        assert_eq!(tempo_from(), TempoSource::Internal);
        assert!(io.lock().unwrap().setup.tracks.iter().all(Option::is_none));
        assert_eq!(keystep(), PortInput::LearnOnly);
        let song = fresh.time.as_ref().unwrap().project();
        assert_eq!(song.tracks.len(), crate::time::TRACKS);
        assert!(song.tracks.iter().all(|t| t.slots.is_empty()));
        assert!(fresh.notes.is_empty(), "{:?}", fresh.notes);
        assert!(p.browser.as_ref().unwrap().project().is_none());
        assert!(!p.browser.as_ref().unwrap().unsaved());

        // The next start, with Prefs > At start on Last project: once the
        // sound is going, the project saved above opens, and the Pads
        // tab's picker stays where it is.
        let lists = p.browser.as_ref().unwrap().lists_text();
        assert!(
            lists.contains(&format!("project = {}\n", loc.to_line())),
            "{lists}"
        );
        let opens = |q: &mut Player| {
            q.tick(0.033);
            q.take_actions().into_iter().find_map(|a| match a {
                FromUi::OpenProject(o) => Some(o),
                _ => None,
            })
        };
        let last = Settings {
            open_last: true,
            ..Default::default()
        };
        let mut q = sample_sampler(Fonts::embedded());
        q.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), &lists);
        q.take_actions();
        q.apply(ToUi::Settings(last.clone()));
        assert!(opens(&mut q).is_none(), "not before the sound is going");
        q.apply(ToUi::ProjectDefaults(defaults()));
        let at_start = opens(&mut q).expect("the last project opens");
        assert_eq!(at_start.what, loc.name());
        assert!(q.browser.as_ref().unwrap().picking().is_none());
        assert!(opens(&mut q).is_none(), "once");
        // New project leaves the empty one.
        let mut n = sample_sampler(Fonts::embedded());
        n.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), &lists);
        n.take_actions();
        n.apply(ToUi::Settings(Settings {
            open_last: false,
            ..Default::default()
        }));
        n.apply(ToUi::ProjectDefaults(defaults()));
        assert!(opens(&mut n).is_none());
        // Last project is the default.
        assert!(Settings::default().open_last);
        // After a crash (a safe start, crash.rs) the last project does
        // not open, and the screen says so.
        let mut c = sample_sampler(Fonts::embedded());
        c.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), &lists);
        c.take_actions();
        c.safe_start();
        c.apply(ToUi::Settings(last.clone()));
        c.apply(ToUi::ProjectDefaults(defaults()));
        assert!(opens(&mut c).is_none(), "a safe start opens nothing");
        let said = crate::crash::screen_line(true, Some(loc.name()), None);
        assert!(said.contains(loc.name()), "{said}");
        assert!(
            events_log(&c)
                .iter()
                .any(|l| *l == format!("project: safe start: {said}")),
            "{:?}",
            events_log(&c)
        );
        assert_eq!(
            c.told.as_ref().map(|t| t.0.clone()),
            Some(tell_text(&said)),
            "on the hint line"
        );
        assert!(opens(&mut c).is_none(), "nor later");
        // A last project gone since is said; the new one stays.
        let mut r = sample_sampler(Fonts::embedded());
        r.set_browser(
            mpfree_browser_ui::Browser::inline(lib.clone()),
            "project = Projects/Nowhere\n",
        );
        r.take_actions();
        r.apply(ToUi::Settings(last));
        r.apply(ToUi::ProjectDefaults(defaults()));
        assert!(opens(&mut r).is_none());
        assert!(
            events_log(&r)
                .iter()
                .any(|l| l.starts_with("project: the last project wasn't opened")),
            "{:?}",
            events_log(&r)
        );
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// Phase 0 of the audio tracks plan (docs/dev/design/project-safety.md):
    /// a project this build can't read whole (clips saved as
    /// `mpfree-clips 9`, as an `mpfree-clips 2` project is to a build from
    /// before it, or a newer project format) doesn't open. Nothing goes to
    /// the engines, the browser still saves to the project that was open,
    /// and the screen says why in plain words.
    #[test]
    fn a_project_this_build_cant_read_doesnt_open_and_the_open_one_stays() {
        use crate::project::{self, Defaults};
        use mpfree_browser_ui::sample::{select, source};
        use mpfree_library::{Loc, Place};
        let dir = std::env::temp_dir().join(format!("mpfree-refused-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        let synth = crate::synth::Synth::new(44_100);
        let good = project::new_snapshot(&Defaults {
            tempo: 120.0,
            mixer: project::mixer_text(&crate::mixing::MixHost::new(44_100, -6.0, 0.0).mixer, 0),
            modu: String::new(),
            synth: project::synth_text(&Default::default(), &synth.sounds()),
        });
        let song = Loc::top(Place::Projects).join("Song").unwrap();
        lib.save_project(&song, &good, 0).unwrap();
        let mut clips_9 = good.clone();
        for (name, text) in &mut clips_9.parts {
            if name == project::CLIPS {
                *text = text.replacen("mpfree-clips 2", "mpfree-clips 9", 1);
            }
        }
        let mut newer = good.clone();
        for (k, v) in &mut newer.meta.extra {
            if k == project::FORMAT_KEY {
                *v = (project::FORMAT + 1).to_string();
            }
        }
        let later = Loc::top(Place::Projects).join("From later").unwrap();
        let newest = Loc::top(Place::Projects).join("Newest").unwrap();
        lib.save_project(&later, &clips_9, 0).unwrap();
        lib.save_project(&newest, &newer, 0).unwrap();
        p.apply(ToUi::Show(View::Browser));
        let open = |p: &mut Player, name: &str| {
            let b = p.browser.as_mut().unwrap();
            b.go_source(source("Projects"));
            select(b, name);
            b.push();
            p.step_browser();
            p.take_actions().into_iter().find_map(|a| match a {
                FromUi::OpenProject(o) => Some(o),
                _ => None,
            })
        };
        let opened = open(&mut p, "Song").expect("Song opens");
        p.apply(ToUi::ProjectBack(opened));
        for (name, why) in [
            ("From later", "its clips can't be read ("),
            ("Newest", "it was saved by a newer MPFree ("),
        ] {
            assert!(open(&mut p, name).is_none(), "{name} went to the engines");
            let b = p.browser.as_ref().unwrap();
            assert_eq!(b.project(), Some(&song), "{name}");
            assert_eq!(b.last_project(), Some(&song), "{name}");
            assert!(!b.unsaved(), "{name}");
            let (line, problem) = b.status_line().unwrap();
            assert!(problem, "{line}");
            assert!(
                line.starts_with(&format!("Didn't open {name}: {why}"))
                    && line.ends_with("The project you had open is unchanged"),
                "{line}"
            );
            let said = format!("project: didn't open {name}: {why}");
            assert!(
                events_log(&p).iter().any(|l| l.starts_with(&said)),
                "{:?}",
                events_log(&p)
            );
        }
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// Autosave (Jay's pick, 14 Nov): unsaved work edited since the last
    /// autosave goes, every 2 minutes, into autosave's own project; a save
    /// the musician asks for wins. At the next start, work autosaved after
    /// the last save is set aside and the screen says where.
    #[test]
    fn unsaved_work_is_autosaved_and_set_aside_at_the_next_start() {
        use crate::project::{self, Collected, Defaults};
        use mpfree_library::project::AUTOSAVE;
        use mpfree_library::{Loc, Meta, Place, Snapshot};
        let dir = std::env::temp_dir().join(format!("mpfree-autosave-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let lib = mpfree_library::Library::at(&dir).unwrap();
        let synth = crate::synth::Synth::new(44_100);
        let mixer = project::mixer_text(&crate::mixing::MixHost::new(44_100, -6.0, 0.0).mixer, 0);
        let synth_text = project::synth_text(&Default::default(), &synth.sounds());
        let defaults = || {
            Box::new(Defaults {
                tempo: 120.0,
                mixer: mixer.clone(),
                modu: String::new(),
                synth: synth_text.clone(),
            })
        };
        let parts = |tempo: f64| {
            Box::new(Collected {
                tempo,
                swing: Default::default(),
                clips: crate::time::TimeHost::new(44_100, tempo)
                    .unwrap()
                    .project()
                    .clone(),
                mixer: mixer.clone(),
                modu: String::new(),
                synth: synth_text.clone(),
                arp: format!("{}\n", crate::app::ARP_HEADER),
                instruments: String::new(),
                track_kits: String::new(),
                instrument_list: crate::instrument_list::InstrumentList::new().text(),
                pads: String::new(),
                perform: String::new(),
                loops: None,
                audio: None,
            })
        };
        // Seconds of ticks, one a second: whether the parts were asked for.
        let asks = |p: &mut Player, secs: usize| {
            let mut asked = false;
            for _ in 0..secs {
                p.tick(1.0);
                asked |= p
                    .take_actions()
                    .iter()
                    .any(|a| matches!(a, FromUi::SaveProject));
            }
            asked
        };
        let edit = |p: &mut Player| {
            p.opened_at = None;
            p.saw_action(&FromUi::Time(TimeAction::NewClip { track: 0, slot: 1 }));
            assert!(p.browser.as_ref().unwrap().unsaved());
        };
        let autosave = Loc::top(Place::Projects).join(AUTOSAVE).unwrap();
        let mut p = sample_sampler(Fonts::embedded());
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        p.apply(ToUi::ProjectDefaults(defaults()));
        // Nothing unsaved, nothing autosaved.
        assert!(!asks(&mut p, 130));
        // Two minutes after an edit, the parts are asked for, and go to
        // autosave's project, quietly: the work stays unsaved and new.
        edit(&mut p);
        assert!(!asks(&mut p, 119));
        assert!(asks(&mut p, 2));
        let log = events_log(&p).len();
        p.apply(ToUi::ProjectParts(parts(101.0)));
        p.step_browser();
        let back = lib.open_project(&autosave).unwrap();
        assert!(back.meta.is_autosave());
        assert_eq!(back.meta.tempo, 101.0);
        assert_eq!(back.meta.name, "Autosave of a new project");
        assert_eq!(events_log(&p).len(), log, "not in the Events log");
        let b = p.browser.as_ref().unwrap();
        assert!(b.unsaved() && b.project().is_none());
        // No edit since: nothing more.
        assert!(!asks(&mut p, 130));
        // Parts asked for that never come are asked for again later; a
        // save the musician asks for meanwhile wins.
        edit(&mut p);
        assert!(asks(&mut p, 121));
        assert!(!asks(&mut p, 237));
        assert!(asks(&mut p, 4));
        p.ask_save();
        assert!(p
            .take_actions()
            .iter()
            .any(|a| matches!(a, FromUi::SaveProject)));
        p.apply(ToUi::ProjectParts(parts(102.0)));
        p.step_browser();
        let saved = p
            .browser
            .as_ref()
            .unwrap()
            .project()
            .cloned()
            .expect("saved");
        assert!(saved.name().starts_with("Project "), "{}", saved.name());
        assert_eq!(lib.open_project(&saved).unwrap().meta.tempo, 102.0);
        assert_eq!(lib.open_project(&autosave).unwrap().meta.tempo, 101.0);
        assert!(!p.browser.as_ref().unwrap().unsaved());
        assert!(!asks(&mut p, 130), "saved: nothing to autosave");

        // The next start, after a crash: the work autosaved after the last
        // save is set aside before anything autosaves, and the safe start
        // says where.
        let at = |secs: u64, tempo: f64| Snapshot {
            meta: Meta {
                tempo,
                saved: secs,
                ..Meta::default()
            },
            parts: vec![("transport".into(), format!("bpm = {tempo}\n"))],
        };
        let old = Loc::top(Place::Projects).join("Old").unwrap();
        lib.save_project(&old, &at(1_000, 90.0), 0).unwrap();
        let autosaved = |secs: u64| {
            let mut s = at(secs, 95.0);
            s.meta.mark_autosave();
            lib.save_project(&lib.autosave_project().unwrap(), &s, 0)
                .unwrap();
        };
        autosaved(2_000); // 1970-01-01 00:33
        let lists = "project = Projects/Old\n";
        let last = Settings {
            open_last: true,
            ..Default::default()
        };
        let opens = |q: &mut Player| {
            q.tick(0.033);
            q.take_actions().into_iter().find_map(|a| match a {
                FromUi::OpenProject(o) => Some(o),
                _ => None,
            })
        };
        let mut c = sample_sampler(Fonts::embedded());
        c.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), lists);
        c.take_actions();
        c.safe_start();
        c.apply(ToUi::Settings(last.clone()));
        c.apply(ToUi::ProjectDefaults(defaults()));
        assert!(opens(&mut c).is_none());
        let kept = Loc::top(Place::Projects)
            .join("Unsaved 1970-01-01 00.33")
            .unwrap();
        assert_eq!(lib.open_project(&kept).unwrap().meta.tempo, 95.0);
        assert!(lib.open_project(&autosave).is_err());
        let said = crate::crash::screen_line(true, Some("Old"), Some(kept.name()));
        assert!(
            events_log(&c)
                .iter()
                .any(|l| *l == format!("project: safe start: {said}")),
            "{:?}",
            events_log(&c)
        );
        assert_eq!(c.told.as_ref().map(|t| t.0.clone()), Some(tell_text(&said)));
        // After the power switch (a normal start): set aside too, said,
        // and the last project opens as Prefs > At start says.
        autosaved(3_000); // 00:50
        let mut n = sample_sampler(Fonts::embedded());
        n.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), lists);
        n.take_actions();
        n.apply(ToUi::Settings(last));
        n.apply(ToUi::ProjectDefaults(defaults()));
        assert_eq!(opens(&mut n).expect("the last project").what, "Old");
        let words = "Unsaved work from the last run is in Projects > Unsaved 1970-01-01 00.50.";
        assert!(
            events_log(&n)
                .iter()
                .any(|l| *l == format!("project: {words}")),
            "{:?}",
            events_log(&n)
        );
        assert!(lib
            .open_project(
                &Loc::top(Place::Projects)
                    .join("Unsaved 1970-01-01 00.50")
                    .unwrap()
            )
            .is_ok());
        // Autosaved before the last save: nothing to set aside or say.
        autosaved(500);
        let mut s = sample_sampler(Fonts::embedded());
        s.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), lists);
        s.take_actions();
        s.apply(ToUi::Settings(Settings {
            open_last: false,
            ..Default::default()
        }));
        s.apply(ToUi::ProjectDefaults(defaults()));
        assert!(opens(&mut s).is_none());
        assert!(!events_log(&s).iter().any(|l| l.contains("Unsaved work")));
        assert!(lib.open_project(&autosave).is_ok(), "left in place");
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn an_exported_pad_goes_to_samples_exports_and_loads_back_with_its_settings_and_slices() {
        use mpfree_library::{Loc, Place};
        use mpfree_sampler_ui::slice_tool::Row;
        let pad = mpfree_sampler_ui::sample::PAD;
        let mut p = sample_sampler(Fonts::embedded());
        let put_on = |p: &mut Player, delta: i32| {
            let index = Row::ALL.iter().position(|r| *r == Row::Put).unwrap();
            p.on_event(UiEvent {
                widget: mpfree_sampler_ui::wave_tab::REGION.into(),
                kind: EventKind::Step { index, delta },
            });
        };
        pick_tool(&mut p, mpfree_sampler_ui::wave_tab::Tool::Slice);
        // Library is offered only once the app has a library to write them
        // in.
        put_on(&mut p, -1);
        assert_ne!(p.sample.slice().unwrap().0.put_text(), "Library");
        put_on(&mut p, 1);
        let root = std::env::temp_dir().join(format!("mpfree-export-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        let lib = mpfree_library::Library::at(&root).unwrap();
        p.set_browser(mpfree_browser_ui::Browser::inline(lib.clone()), "");
        p.take_actions();
        put_on(&mut p, -1);
        assert_eq!(p.sample.slice().unwrap().0.put_text(), "Library");
        let n = p.sample.slice().unwrap().0.slices();
        let export = |p: &mut Player| {
            p.on_event(UiEvent {
                widget: mpfree_sampler_ui::wave_tab::REGION.into(),
                kind: EventKind::Tab(Row::Chop.index()),
            })
        };
        export(&mut p);
        assert!(
            events_log(&p).iter().any(|l| l
                == &format!(
                    "sample: pad A5 exported as {} files: Break 92.wav with its settings \
                     (Break 92.mpfree) and {n} slices (Break 92 01.wav to Break 92 {n:02}.wav)",
                    2 + n
                )),
            "{:?}",
            events_log(&p)
        );
        // Written on a thread into a folder of its own in Samples /
        // Exports, which is made for it.
        let saved = "sample: Break 92 saved in Samples / Exports / Break 92";
        tick_until(&mut p, |p| events_log(p).iter().any(|l| l == saved));
        assert!(views(p.take_actions()).0.is_empty(), "the kit is as it was");
        let at = Loc::new(Place::Samples, &["Exports", "Break 92"]).unwrap();
        let listed = lib.list(&at).unwrap();
        let mut names: Vec<&str> = listed.iter().map(|e| e.name.as_str()).collect();
        names.sort_unstable();
        assert_eq!(names.len(), 2 + n, "the sound, its settings, the slices");
        assert!(names.contains(&"Break 92.wav") && names.contains(&"Break 92.mpfree"));
        assert!(names.contains(&format!("Break 92 {n:02}.wav").as_str()));
        // Exported again, it takes the next free name.
        export(&mut p);
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l == "sample: Break 92 saved in Samples / Exports / Break 92 2")
        });
        // Load to pad brings the pad back on another pad, slices and all,
        // as one undo step.
        let dir = lib
            .file_path(&at.join("Break 92.wav").unwrap())
            .unwrap()
            .parent()
            .unwrap()
            .to_path_buf();
        let chops = p.sample.project(0).unwrap().chop_sets.len();
        p.sample.load_file(dir.join("Break 92.wav"), true);
        tick_until(&mut p, |p| p.sample.assigning().is_some());
        p.apply(ToUi::PadDown {
            pad: 9,
            velocity: 100,
        });
        p.apply(ToUi::PadUp(9));
        p.tick(0.033);
        let kit = p.sample.project(0).unwrap();
        assert_eq!(kit.pad(9), kit.pad(pad), "the pad as it was");
        assert_eq!(kit.chop_sets.len(), chops + 1);
        assert_eq!(kit.chop_sets.last().unwrap().slices(), n);
        assert_eq!(p.kits[0].pads[9].as_deref(), Some("Break 92"));
        assert!(events_log(&p).iter().any(|l| l
            == "sample: loaded: Break 92 on pad A10, with its settings and its slices from Break 92.mpfree"));
        p.apply(ToUi::SampleUndo(false));
        let kit = p.sample.project(0).unwrap();
        assert!(kit.pad(9).is_none());
        assert_eq!(kit.chop_sets.len(), chops);
        // A slice loads as a sound of its own; settings that can't be
        // read leave the sound alone, and say so.
        p.sample.load_file(dir.join("Break 92 02.wav"), false);
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l.starts_with("sample: loaded: Break 92 02, "))
        });
        std::fs::write(dir.join("Break 92.mpfree"), "junk").unwrap();
        p.sample.load_file(dir.join("Break 92.wav"), false);
        tick_until(&mut p, |p| {
            events_log(p).iter().any(|l| {
                l == "sample: Break 92: its settings (Break 92.mpfree) not used \
                      (not an mpfree-sampler 1 part); the sound alone is loaded"
            })
        });
        std::fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn normalize_sets_the_gain_from_the_peak_in_one_undo_step() {
        use mpfree_sampler_ui::wave_tab::{Row, REGION};
        let mut p = sample_sampler(Fonts::embedded());
        let st = p.sample.state().unwrap().clone();
        let kit = p.sample.project(0).unwrap();
        let peak = st.region.peak(kit.source(st.region.source).unwrap());
        assert!(peak > 0.0, "{peak}");
        let press = |p: &mut Player| {
            p.on_event(UiEvent {
                widget: REGION.into(),
                kind: EventKind::Tab(Row::Normalize.index()),
            })
        };
        press(&mut p);
        let gain = p.sample.state().unwrap().region.gain_db;
        let peak_db = 20.0 * peak.log10();
        assert_eq!(gain, (-peak_db * 10.0).floor() / 10.0);
        let loudest = peak * 10f32.powf(gain / 20.0);
        assert!(loudest <= 1.0 && loudest > 0.988, "{loudest}");
        assert!(
            events_log(&p).iter().any(|l| l
                == &format!(
                "sample: pad A5 normalized: its peak {peak_db:.1} dB, gain {:+.1} -> {gain:+.1} dB",
                st.region.gain_db
            )),
            "{:?}",
            events_log(&p)
        );
        // Again, it is where it was: the same gain.
        press(&mut p);
        assert_eq!(p.sample.state().unwrap().region.gain_db, gain);
        // One undo step each.
        p.apply(ToUi::SampleUndo(false));
        assert_eq!(p.sample.state().unwrap().region.gain_db, gain);
        p.apply(ToUi::SampleUndo(false));
        assert_eq!(p.sample.state().unwrap().region.gain_db, st.region.gain_db);
        // A silent region is left as it is, and says so.
        let src = st.region.source;
        let silent = {
            let s = p.sample.project(0).unwrap().source(src).unwrap();
            let ch = usize::from(s.channels());
            (0..s.frames() as usize)
                .find(|&f| (f * ch..f * ch + ch).all(|i| s.data().get(i) == 0.0))
                .expect("a silent frame in the break") as u64
        };
        p.sample
            .project_mut(0)
            .unwrap()
            .edit_pad(st.pad, None, |pd| {
                let r = &mut pd.layers[0].region;
                (r.start, r.end, r.sustain_loop) = (silent, silent + 1, None);
                r.mode = mpfree_sampler::model::PlayMode::OneShot;
                (r.fade_in.frames, r.fade_out.frames) = (0, 0);
            })
            .unwrap();
        press(&mut p);
        let kit = p.sample.project(0).unwrap();
        let r = &kit.pad(st.pad).unwrap().layers[0].region;
        assert_eq!((r.start, r.gain_db), (silent, st.region.gain_db));
        assert!(events_log(&p)
            .iter()
            .any(|l| l == "sample: pad A5 not normalized: it is silent"));
    }

    #[test]
    fn process_makes_a_new_sound_on_a_worker_in_one_undo_step_and_can_be_stopped() {
        use mpfree_sampler::model::WarpMethod;
        use mpfree_sampler_ui::warp_tool::{self, Row};
        use mpfree_sampler_ui::wave_tab::REGION as LIST;
        use mpfree_sampler_ui::widgets::SettingList;
        let mut p = sample_sampler(Fonts::embedded());
        warp_page(&mut p);
        assert_eq!(p.page(), crate::sample_page::PAGE);
        let ev = |p: &mut Player, kind: EventKind| {
            p.on_event(UiEvent {
                widget: LIST.into(),
                kind,
            })
        };
        let step = |p: &mut Player, row: Row, delta: i32| {
            ev(
                p,
                EventKind::Step {
                    index: row.index(),
                    delta,
                },
            );
            p.apply(ToUi::SampleLift);
        };
        let process = |p: &mut Player| ev(p, EventKind::Tab(Row::Process.index()));
        let value = |p: &Player, row: Row| {
            p.ui.get::<SettingList>(LIST).unwrap().rows[row.index()]
                .value
                .clone()
        };
        let before = p.sample.state().unwrap().region.clone();
        // Not warped and the new sound's pitch 0: it would come out the same.
        process(&mut p);
        assert!(events_log(&p).iter().any(|l| l
            == "sample: pad A5 not processed (it would come out the same: set New sound's pitch, or turn Warp on)"));
        assert_eq!(value(&p, Row::Process), warp_tool::PROCESS_TEXT);
        // Three semitones up: the same length, a new sound.
        for _ in 0..3 {
            step(&mut p, Row::Shift, 1);
        }
        process(&mut p);
        assert!(events_log(&p)
            .iter()
            .any(|l| l == "sample: processing pad A5: 3 semitones higher"));
        assert!(value(&p, Row::Process).starts_with("Stop · "));
        tick_until(&mut p, |p| {
            events_log(p).iter().any(|l| {
                l.starts_with("sample: pad A5 processed into a new sound, 3 semitones higher: ")
            })
        });
        assert_eq!(value(&p, Row::Process), warp_tool::PROCESS_TEXT);
        let after = p.sample.state().unwrap().region.clone();
        let kit = p.sample.project(0).unwrap();
        let made = kit.source(after.source).unwrap();
        assert_ne!(after.source, before.source);
        assert!(made.name.ends_with(" +3st"), "{}", made.name);
        assert_eq!((after.start, after.end), (0, before.frames()));
        assert_eq!(after.mode, before.mode);
        p.apply(ToUi::SampleUndo(false));
        assert_eq!(p.sample.state().unwrap().region, before, "one undo step");
        // Stretched from its own tempo to the project's.
        for _ in 0..3 {
            step(&mut p, Row::Shift, -1);
        }
        step(&mut p, Row::Warp, 1);
        let w = p.sample.state().unwrap().region.warp.clone().unwrap();
        assert_eq!(w.method, WarpMethod::Stretch);
        let tempo = p.sample.tempo();
        assert!((f64::from(w.bpm) - tempo).abs() > 1.0, "{} {tempo}", w.bpm);
        process(&mut p);
        let words = format!("stretched from {:.1} to {tempo:.1} BPM", w.bpm);
        assert!(
            events_log(&p)
                .iter()
                .any(|l| l == &format!("sample: processing pad A5: {words}")),
            "{:?}",
            events_log(&p)
        );
        tick_until(&mut p, |p| {
            events_log(p).iter().any(|l| {
                l.starts_with(&format!(
                    "sample: pad A5 processed into a new sound, {words}: "
                ))
            })
        });
        let r = p.sample.state().unwrap().region.clone();
        let want = before.frames() as f64 * f64::from(w.bpm) / tempo;
        assert!(
            (r.frames() as f64 - want).abs() <= 2.0,
            "{} {want}",
            r.frames()
        );
        let nw = r.warp.unwrap();
        assert_eq!(nw.method, WarpMethod::Stretch);
        assert!(
            (f64::from(nw.bpm) - tempo).abs() < 0.01,
            "it is at the project tempo now"
        );
        p.apply(ToUi::SampleUndo(false));
        // Stopped: nothing changes.
        let now = p.sample.state().unwrap().region.clone();
        process(&mut p);
        process(&mut p);
        tick_until(&mut p, |p| {
            events_log(p)
                .iter()
                .any(|l| l == "sample: pad A5 not processed (stopped)")
        });
        assert_eq!(p.sample.state().unwrap().region, now);
        assert_eq!(value(&p, Row::Process), warp_tool::PROCESS_TEXT);
    }

    /// The Play, Pads and Sequencer redesign (Jay, 18 Nov): the browser's
